export default {"file":"staff-management.html","title":"Schoolix - Staff Management","htmlClass":"","bodyClass":"sx-admin-app","body":"\r\n<div id=\"sxPageLoader\" class=\"sx-page-loader\" role=\"status\" aria-live=\"polite\">\r\n  <section class=\"dots-container\" aria-label=\"Loading page\">\r\n    <div class=\"dot\"></div><div class=\"dot\"></div><div class=\"dot\"></div><div class=\"dot\"></div><div class=\"dot\"></div>\r\n  </section>\r\n</div>\r\n<main class=\"staff-page\">\r\n  <section class=\"hero\">\r\n    <div>\r\n      <h1>Staff Management</h1>\r\n      <p>Teachers, librarians, accountants, and other staff accounts in one place.</p>\r\n    </div>\r\n    <div class=\"hero-actions\">\r\n      <a class=\"btn btn-light\" href=\"#/teachers.html\"><i class=\"fas fa-chalkboard-teacher\"></i> Teacher Desk</a>\r\n      <a class=\"btn btn-light\" href=\"#/library-management.html\"><i class=\"fas fa-book-open\"></i> Library Staff</a>\r\n      <a class=\"btn btn-light\" href=\"#/accountant-management.html\"><i class=\"fas fa-user-tie\"></i> Accountants</a>\r\n    </div>\r\n  </section>\r\n\r\n  <section class=\"stats\">\r\n    <div class=\"stat\"><span>Total Staff</span><strong id=\"statTotal\">0</strong></div>\r\n    <div class=\"stat\"><span>Teachers</span><strong id=\"statTeachers\">0</strong></div>\r\n    <div class=\"stat\"><span>Librarians</span><strong id=\"statLibrarians\">0</strong></div>\r\n    <div class=\"stat\"><span>Accountants</span><strong id=\"statAccountants\">0</strong></div>\r\n  </section>\r\n\r\n  <section class=\"panel\">\r\n    <div class=\"panel-head\">\r\n      <div>\r\n        <h2>Add Staff</h2>\r\n        <div class=\"muted\">Teachers, librarians, and accountants get portal login. Other Staff is saved for records and salary only.</div>\r\n      </div>\r\n    </div>\r\n    <form id=\"staffForm\">\r\n      <div class=\"grid form-grid\">\r\n        <div>\r\n          <label for=\"staffRole\">Role</label>\r\n          <select id=\"staffRole\" required>\r\n            <option value=\"teacher\">Teacher</option>\r\n            <option value=\"librarian\">Librarian</option>\r\n            <option value=\"accountant\">Accountant</option>\r\n            <option value=\"staff\">Other Staff</option>\r\n          </select>\r\n        </div>\r\n        <div>\r\n          <label for=\"staffName\">Name</label>\r\n          <input id=\"staffName\" type=\"text\" placeholder=\"Full name\" required>\r\n        </div>\r\n        <div id=\"staffEmailField\" class=\"login-field\">\r\n          <label for=\"staffEmail\">Email</label>\r\n          <input id=\"staffEmail\" type=\"email\" placeholder=\"staff@school.com\" required>\r\n        </div>\r\n        <div id=\"staffPasswordField\" class=\"login-field\">\r\n          <label for=\"staffPassword\">Password</label>\r\n          <input id=\"staffPassword\" type=\"password\" placeholder=\"Minimum 6 characters\" minlength=\"6\" required>\r\n        </div>\r\n        <div>\r\n          <label for=\"staffSalary\">Monthly Salary</label>\r\n          <input id=\"staffSalary\" type=\"number\" min=\"0\" placeholder=\"0\">\r\n        </div>\r\n      </div>\r\n      <div id=\"otherFields\" class=\"grid other-fields\">\r\n        <div>\r\n          <label for=\"staffDesignation\">Who is this staff?</label>\r\n          <input id=\"staffDesignation\" type=\"text\" placeholder=\"Receptionist, Guard, Driver, Clerk\">\r\n        </div>\r\n        <div>\r\n          <label for=\"staffDepartment\">Department / Work</label>\r\n          <input id=\"staffDepartment\" type=\"text\" placeholder=\"Office, Transport, Security\">\r\n        </div>\r\n      </div>\r\n      <div id=\"teacherFields\" class=\"grid teacher-fields show\">\r\n        <div>\r\n          <label for=\"teacherClass\">Class</label>\r\n          <input id=\"teacherClass\" type=\"text\" placeholder=\"10\">\r\n        </div>\r\n        <div>\r\n          <label for=\"teacherSection\">Section</label>\r\n          <input id=\"teacherSection\" type=\"text\" placeholder=\"A\">\r\n        </div>\r\n        <div>\r\n          <label for=\"teacherSubject\">Subject</label>\r\n          <input id=\"teacherSubject\" type=\"text\" placeholder=\"Mathematics\">\r\n        </div>\r\n      </div>\r\n      <div style=\"margin-top: 14px;\">\r\n        <button id=\"createStaffBtn\" class=\"btn btn-primary\" type=\"submit\"><i class=\"fas fa-user-plus\"></i> Create Staff Account</button>\r\n      </div>\r\n    </form>\r\n  </section>\r\n\r\n  <section class=\"panel\">\n    <div class=\"panel-head\">\n      <div>\n        <h2>Staff Salary</h2>\n        <div class=\"muted\">Generate monthly salary records and record payments. Paid salary is posted as debit in School Accounts ledger.</div>\r\n      </div>\r\n      <a class=\"btn btn-light\" href=\"#/school-accounts.html\"><i class=\"fas fa-book\"></i> Open Ledger</a>\r\n    </div>\r\n    <div class=\"salary-layout\">\r\n      <form id=\"salaryForm\" class=\"salary-form\">\r\n        <div>\r\n          <label for=\"salaryStaffSelect\">Staff</label>\r\n          <select id=\"salaryStaffSelect\" required><option value=\"\">Loading staff...</option></select>\r\n        </div>\r\n        <div>\r\n          <label for=\"salaryMonth\">Salary Month</label>\r\n          <input id=\"salaryMonth\" type=\"month\" required>\r\n        </div>\r\n        <button class=\"btn btn-primary\" type=\"button\" id=\"generateSalaryBtn\"><i class=\"fas fa-file-invoice\"></i> Generate / Select Salary</button>\r\n        <div>\r\n          <label for=\"paymentAmount\">Payment Amount</label>\r\n          <input id=\"paymentAmount\" type=\"number\" min=\"0.01\" step=\"0.01\" placeholder=\"0.00\">\r\n        </div>\r\n        <div>\r\n          <label for=\"paymentDate\">Payment Date</label>\r\n          <input id=\"paymentDate\" type=\"date\">\r\n        </div>\r\n        <div>\r\n          <label for=\"paymentMode\">Payment Mode</label>\r\n          <select id=\"paymentMode\">\r\n            <option>Cash</option>\r\n            <option>Bank Transfer</option>\r\n            <option>UPI</option>\r\n            <option>Cheque</option>\r\n            <option>Card</option>\r\n            <option>Other</option>\r\n          </select>\r\n        </div>\r\n        <div>\r\n          <label for=\"paymentNote\">Note</label>\r\n          <input id=\"paymentNote\" type=\"text\" maxlength=\"160\" placeholder=\"Optional note\">\r\n        </div>\r\n        <button class=\"btn btn-success\" type=\"submit\" id=\"recordSalaryBtn\" disabled><i class=\"fas fa-indian-rupee-sign\"></i> Record Payment</button>\r\n      </form>\r\n      <div>\n        <div id=\"activeSalaryHint\" class=\"empty\">Select staff and month to generate salary.</div>\n        <div id=\"salaryRecordsList\" class=\"salary-records\" style=\"display: none;\" hidden></div>\n      </div>\n    </div>\n  </section>\n\n  <section class=\"panel\">\n    <div class=\"panel-head\">\n      <div>\n        <h2>All Staff</h2>\n        <div class=\"muted\">Search, edit, activate, or remove staff accounts without touching old role-specific pages.</div>\n      </div>\n    </div>\n    <div class=\"filters\">\n      <input id=\"staffSearch\" type=\"search\" placeholder=\"Search name, email, ID, class, subject\">\n      <select id=\"roleFilter\">\n        <option value=\"all\">All roles</option>\n        <option value=\"teacher\">Teachers</option>\n        <option value=\"librarian\">Librarians</option>\n        <option value=\"accountant\">Accountants</option>\n        <option value=\"staff\">Other Staff</option>\n      </select>\n      <select id=\"statusFilter\">\n        <option value=\"active\">Active</option>\n        <option value=\"all\">All status</option>\n        <option value=\"removed\">Removed</option>\n      </select>\n      <select id=\"staffPageSize\" class=\"staff-page-size\" aria-label=\"Rows per page\">\n        <option value=\"10\">10 / page</option>\n        <option value=\"25\">25 / page</option>\n        <option value=\"50\">50 / page</option>\n      </select>\n    </div>\n    <div id=\"staffList\" class=\"staff-list\" style=\"margin-top: 14px;\"></div>\n    <div id=\"staffPagination\" class=\"staff-pagination\" hidden>\n      <div id=\"staffPaginationInfo\" class=\"staff-pagination-info\"></div>\n      <div class=\"staff-pagination-actions\">\n        <button class=\"btn btn-light\" type=\"button\" id=\"staffPrevPage\"><i class=\"fas fa-chevron-left\"></i> Prev</button>\n        <button class=\"btn btn-light\" type=\"button\" id=\"staffNextPage\">Next <i class=\"fas fa-chevron-right\"></i></button>\n      </div>\n    </div>\n  </section>\n</main>\n\r\n<div id=\"editDialog\" class=\"dialog-backdrop\" aria-hidden=\"true\">\r\n  <div class=\"dialog\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"editDialogTitle\">\r\n    <div class=\"dialog-title\">\r\n      <h2 id=\"editDialogTitle\">Edit Staff</h2>\r\n      <button class=\"btn btn-light\" type=\"button\" id=\"closeEditBtn\" aria-label=\"Close\"><i class=\"fas fa-times\"></i></button>\r\n    </div>\r\n    <form id=\"editForm\">\r\n      <input id=\"editUid\" type=\"hidden\">\r\n      <div class=\"edit-grid\">\r\n        <div>\r\n          <label for=\"editName\">Name</label>\r\n          <input id=\"editName\" type=\"text\" required>\r\n        </div>\r\n        <div>\r\n          <label for=\"editEmail\">Email</label>\r\n          <input id=\"editEmail\" type=\"email\" required>\r\n        </div>\r\n        <div>\r\n          <label for=\"editRole\">Role</label>\r\n          <select id=\"editRole\" required>\r\n            <option value=\"teacher\">Teacher</option>\r\n            <option value=\"librarian\">Librarian</option>\r\n            <option value=\"accountant\">Accountant</option>\r\n            <option value=\"staff\">Other Staff</option>\r\n          </select>\r\n        </div>\r\n        <div>\r\n          <label for=\"editStaffId\">Staff/Teacher ID</label>\r\n          <input id=\"editStaffId\" type=\"text\">\r\n        </div>\r\n        <div>\r\n          <label for=\"editClass\">Class</label>\r\n          <input id=\"editClass\" type=\"text\">\r\n        </div>\r\n        <div>\r\n          <label for=\"editSection\">Section</label>\r\n          <input id=\"editSection\" type=\"text\">\r\n        </div>\r\n        <div>\r\n          <label for=\"editSubject\">Subject</label>\r\n          <input id=\"editSubject\" type=\"text\">\r\n        </div>\r\n        <div>\r\n          <label for=\"editSalary\">Monthly Salary</label>\r\n          <input id=\"editSalary\" type=\"number\" min=\"0\">\r\n        </div>\r\n        <div>\r\n          <label for=\"editDesignation\">Designation</label>\r\n          <input id=\"editDesignation\" type=\"text\">\r\n        </div>\r\n        <div>\r\n          <label for=\"editDepartment\">Department / Work</label>\r\n          <input id=\"editDepartment\" type=\"text\">\r\n        </div>\r\n      </div>\r\n      <div class=\"dialog-actions\">\r\n        <button class=\"btn btn-light\" type=\"button\" id=\"cancelEditBtn\">Cancel</button>\r\n        <button class=\"btn btn-primary\" type=\"submit\"><i class=\"fas fa-save\"></i> Save Changes</button>\r\n      </div>\r\n    </form>\r\n  </div>\r\n</div>\r\n\r\n<script src=\"school-branding.js\"></script>\n<script>\n(function () {\n  function escapeLoaderText(value) {\n    return String(value || \"\").replace(/[&<>\"']/g, function (char) {\n      return ({ \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", '\"': \"&quot;\", \"'\": \"&#39;\" })[char];\n    });\n  }\n  function skeletonRows(count) {\n    var rows = \"\";\n    for (var i = 0; i < count; i += 1) {\n      rows += '<div class=\"staff-skeleton\"><div class=\"staff-skeleton-line title\"></div><div class=\"staff-skeleton-line meta\"></div><div class=\"staff-skeleton-line short\"></div></div>';\n    }\n    return '<div class=\"staff-loader\" aria-hidden=\"true\">' + rows + \"</div>\";\n  }\n  function setLoader(id, message, count) {\n    var list = document.getElementById(id);\n    if (!list) return;\n    if (list.hidden || list.style.display === \"none\") return;\n    list.setAttribute(\"aria-busy\", \"true\");\n    list.innerHTML = '<div class=\"staff-inline-loader\"><i class=\"fas fa-spinner fa-spin\"></i>' + escapeLoaderText(message) + \"</div>\" + skeletonRows(count);\n  }\n  function setFallback(id, message) {\n    var list = document.getElementById(id);\n    if (!list || list.getAttribute(\"aria-busy\") !== \"true\") return;\n    if (list.hidden || list.style.display === \"none\") return;\n    list.removeAttribute(\"aria-busy\");\n    list.innerHTML = '<div class=\"empty\">' + escapeLoaderText(message) + \"</div>\";\n  }\n  window.SchoolixStaffManagementLoading = {\n    staff: function (message) { setLoader(\"staffList\", message || \"Loading staff management...\", 5); },\n    salary: function (message) { setLoader(\"salaryRecordsList\", message || \"Loading salary desk...\", 3); },\n    fallback: function () {\n      setFallback(\"staffList\", \"Staff data could not be loaded. Please refresh or sign in again.\");\n      setFallback(\"salaryRecordsList\", \"Salary desk could not be loaded.\");\n    }\n  };\n  window.SchoolixStaffManagementLoading.staff();\n  window.SchoolixStaffManagementLoading.salary();\n  window.setTimeout(function () {\n    if (!window.SchoolixStaffManagementModuleLoaded) window.SchoolixStaffManagementLoading.fallback();\n  }, 18000);\n}());\n</script>\n<script type=\"module\">\nimport { initializeApp } from \"./firebase-compat.js?v=staff-loaders-20260806\";\nimport {\r\n  getAuth,\r\n  createUserWithEmailAndPassword,\r\n  onAuthStateChanged,\r\n  signOut\r\n} from \"./firebase-compat.js?v=staff-loaders-20260806\";\nimport {\r\n  getFirestore,\r\n  doc,\r\n  setDoc,\r\n  getDoc,\r\n  getDocs,\r\n  collection,\r\n  serverTimestamp,\r\n  query,\r\n  where\r\n} from \"./firebase-compat.js?v=staff-loaders-20260806\";\nimport { newLedgerTransactionId, syncStaffSalaryDebit } from \"./accounts-ledger.js?v=staff-loaders-20260806\";\n\nwindow.SchoolixStaffManagementModuleLoaded = true;\n\nconst firebaseConfig = {\n  apiKey: \"AIzaSyAomGwef93HFT9Xyx7SVW95FPw_IcIAICE\",\r\n  authDomain: \"schoolix-48107.firebaseapp.com\",\r\n  projectId: \"schoolix-48107\",\r\n  storageBucket: \"schoolix-48107.firebasestorage.app\",\r\n  messagingSenderId: \"133937954491\",\r\n  appId: \"1:133937954491:web:69d8064422617eb8c4339e\"\r\n};\r\n\r\nconst app = initializeApp(firebaseConfig);\r\nconst auth = getAuth(app);\r\nconst db = getFirestore(app);\r\nconst staffCreatorApp = initializeApp(firebaseConfig, \"staffManagementCreatorApp\");\r\nconst staffCreatorAuth = getAuth(staffCreatorApp);\r\nconst staffRoles = [\"teacher\", \"librarian\", \"accountant\", \"staff\"];\r\nlet adminUID = \"\";\r\nlet staffRecords = [];\nlet salaryRecords = [];\nlet activeSalaryRecordId = \"\";\nlet activeSalaryRecord = null;\nlet staffPage = 1;\n\r\nconst $ = (id) => document.getElementById(id);\r\nconst clean = (value) => String(value || \"\").replace(/\\s+/g, \" \").trim();\r\nconst lower = (value) => clean(value).toLowerCase();\r\nconst money = (value) => Number.isFinite(Number(value)) ? Number(value) : 0;\r\nconst roleLabel = (role) => ({ teacher: \"Teacher\", librarian: \"Librarian\", accountant: \"Accountant\", staff: \"Other Staff\" }[role] || clean(role) || \"Staff\");\r\nconst isRemoved = (staff) => staff.removedFromPanel === true || staff.panelStatus === \"removed\" || staff.active === false;\r\nconst todayISO = () => new Date().toISOString().slice(0, 10);\r\nconst currentMonth = () => todayISO().slice(0, 7);\nconst monthLabel = (value) => value ? new Date(`${value}-01T12:00:00`).toLocaleDateString(\"en-IN\", { month: \"long\", year: \"numeric\" }) : \"Salary\";\nconst salaryStatus = (net, paid) => paid <= 0 ? \"Unpaid\" : paid >= net ? \"Paid\" : \"Partially Paid\";\nconst moneyLabel = (value) => `Rs ${money(value).toLocaleString(\"en-IN\")}`;\n\nfunction staffSkeletonRows(count = 4) {\n  return `<div class=\"staff-loader\" aria-hidden=\"true\">${Array.from({ length: count }).map(() => `\n    <div class=\"staff-skeleton\">\n      <div class=\"staff-skeleton-line title\"></div>\n      <div class=\"staff-skeleton-line meta\"></div>\n      <div class=\"staff-skeleton-line short\"></div>\n    </div>\n  `).join(\"\")}</div>`;\n}\n\nfunction setStaffBusy(element, busy, busyHtml = \"\") {\n  if (!element) return;\n  if (busy) {\n    element.dataset.originalHtml = element.dataset.originalHtml || element.innerHTML;\n    element.disabled = true;\n    element.setAttribute(\"aria-busy\", \"true\");\n    if (busyHtml) element.innerHTML = busyHtml;\n    return;\n  }\n  element.disabled = false;\n  element.removeAttribute(\"aria-busy\");\n  if (element.dataset.originalHtml) {\n    element.innerHTML = element.dataset.originalHtml;\n    delete element.dataset.originalHtml;\n  }\n}\n\nfunction showStaffListLoader(message = \"Loading staff records...\") {\n  const list = $(\"staffList\");\n  if (!list) return;\n  list.setAttribute(\"aria-busy\", \"true\");\n  list.innerHTML = `<div class=\"staff-inline-loader\"><i class=\"fas fa-spinner fa-spin\"></i>${escapeHtml(message)}</div>${staffSkeletonRows(5)}`;\n  $(\"staffPagination\").hidden = true;\n}\n\nfunction showSalaryLoader(message = \"Loading salary records...\") {\n  const list = $(\"salaryRecordsList\");\n  if (!list) return;\n  if (list.hidden || list.style.display === \"none\") return;\n  list.setAttribute(\"aria-busy\", \"true\");\n  list.innerHTML = `<div class=\"staff-inline-loader\"><i class=\"fas fa-spinner fa-spin\"></i>${escapeHtml(message)}</div>${staffSkeletonRows(3)}`;\n}\n\nfunction escapeHtml(value) {\n  return String(value || \"\")\n    .replace(/&/g, \"&amp;\")\r\n    .replace(/</g, \"&lt;\")\r\n    .replace(/>/g, \"&gt;\")\r\n    .replace(/\"/g, \"&quot;\")\r\n    .replace(/'/g, \"&#39;\");\r\n}\r\n\r\nfunction initials(name, fallback = \"S\") {\r\n  const words = clean(name).split(\" \").filter(Boolean);\r\n  return (words.length ? words.slice(0, 2).map((word) => word[0]).join(\"\") : fallback).toUpperCase();\r\n}\r\n\r\nfunction staffKey(staff = {}) {\r\n  return clean(staff.teacherId || staff.staffId || staff.employeeId || staff.uid || \"\");\r\n}\r\n\r\nfunction staffDesignation(staff = {}) {\n  const role = lower(staff.role);\n  if (role === \"teacher\") return staff.subject || \"Teacher\";\n  if (role === \"librarian\") return \"Librarian\";\n  if (role === \"accountant\") return \"Accountant\";\n  return staff.designation || staff.department || \"Other Staff\";\n}\n\nfunction salaryCollectionForRole(role = \"\") {\n  return lower(role) === \"teacher\" ? \"teacher_salary_records\" : \"staff_salary_records\";\n}\n\nfunction salaryCollectionForRecord(record = {}) {\n  return record.salaryCollection || (lower(record.staffRole || record.role) === \"teacher\" || record.sourceType === \"teacher_salary\"\n    ? \"teacher_salary_records\"\n    : \"staff_salary_records\");\n}\n\r\nasync function generateStaffId(role) {\n  const prefix = role === \"teacher\" ? \"TCH\" : role === \"librarian\" ? \"LIB\" : role === \"accountant\" ? \"ACC\" : \"STF\";\n  const existing = new Set(staffRecords.map((staff) => staffKey(staff)).filter(Boolean).map((id) => id.toUpperCase()));\n  const nextNumber = staffRecords.reduce((max, staff) => {\n    const id = staffKey(staff).toUpperCase();\n    const match = id.match(new RegExp(`^${prefix}-?(\\\\d+)$`));\n    return match ? Math.max(max, Number(match[1]) || 0) : max;\n  }, 0) + 1;\n  let number = nextNumber;\n  let id = \"\";\n  do {\n    id = `${prefix}-${String(number).padStart(3, \"0\")}`;\n    number += 1;\n  } while (existing.has(id));\n  return id;\n}\n\r\nfunction setStats() {\r\n  const activeStaff = staffRecords.filter((staff) => !isRemoved(staff));\r\n  $(\"statTotal\").textContent = activeStaff.length.toLocaleString(\"en-IN\");\r\n  $(\"statTeachers\").textContent = activeStaff.filter((staff) => lower(staff.role) === \"teacher\").length.toLocaleString(\"en-IN\");\r\n  $(\"statLibrarians\").textContent = activeStaff.filter((staff) => lower(staff.role) === \"librarian\").length.toLocaleString(\"en-IN\");\r\n  $(\"statAccountants\").textContent = activeStaff.filter((staff) => lower(staff.role) === \"accountant\").length.toLocaleString(\"en-IN\");\r\n}\r\n\r\nfunction matchesSearch(staff, search) {\n  if (!search) return true;\r\n  return [\r\n    staff.name,\r\n    staff.email,\r\n    staff.role,\r\n    staff.teacherId,\r\n    staff.staffId,\r\n      staff.employeeId,\r\n      staff.class,\r\n      staff.section,\r\n      staff.subject,\r\n      staff.designation,\r\n      staff.department\r\n  ].some((value) => lower(value).includes(search));\r\n}\n\nfunction resetStaffPage() {\n  staffPage = 1;\n}\n\nfunction renderStaff() {\n  $(\"staffList\").removeAttribute(\"aria-busy\");\n  setStats();\n  const search = lower($(\"staffSearch\").value);\n  const roleFilter = $(\"roleFilter\").value;\n  const statusFilter = $(\"statusFilter\").value;\n  const pageSize = Math.max(1, Number($(\"staffPageSize\")?.value || 10));\n  const rows = staffRecords\n    .filter((staff) => staffRoles.includes(lower(staff.role)))\r\n    .filter((staff) => roleFilter === \"all\" || lower(staff.role) === roleFilter)\r\n    .filter((staff) => statusFilter === \"all\" || (statusFilter === \"removed\" ? isRemoved(staff) : !isRemoved(staff)))\r\n    .filter((staff) => matchesSearch(staff, search))\r\n    .sort((a, b) => `${lower(a.role)}-${lower(a.name)}`.localeCompare(`${lower(b.role)}-${lower(b.name)}`));\r\n\n  if (!rows.length) {\n    $(\"staffList\").innerHTML = `<div class=\"empty\">No staff matched the current filters.</div>`;\n    $(\"staffPagination\").hidden = true;\n    return;\n  }\n\n  const totalPages = Math.max(1, Math.ceil(rows.length / pageSize));\n  staffPage = Math.min(Math.max(1, staffPage), totalPages);\n  const start = (staffPage - 1) * pageSize;\n  const visibleRows = rows.slice(start, start + pageSize);\n\n  $(\"staffList\").innerHTML = visibleRows.map((staff) => {\n    const role = lower(staff.role);\r\n    const removed = isRemoved(staff);\r\n    const meta = [\r\n      staff.email || \"No email\",\r\n      staffKey(staff) ? `ID: ${staffKey(staff)}` : \"\",\r\n      staff.class ? `Class ${staff.class}${staff.section ? \"-\" + staff.section : \"\"}` : \"\",\r\n      staff.subject ? `Subject: ${staff.subject}` : \"\",\r\n      lower(staff.role) === \"staff\" ? `Designation: ${staffDesignation(staff)}` : \"\",\r\n      staff.monthlySalary ? `Salary: Rs ${money(staff.monthlySalary).toLocaleString(\"en-IN\")}` : \"\"\r\n    ].filter(Boolean).join(\" | \");\r\n    return `\r\n      <article class=\"staff-row\">\r\n        <div class=\"identity\">\r\n          <div class=\"avatar\">${escapeHtml(initials(staff.name || staff.email, role[0] || \"S\"))}</div>\r\n          <div class=\"staff-main\">\r\n            <strong>${escapeHtml(staff.name || \"Unnamed Staff\")}</strong>\r\n            <small>${escapeHtml(meta)}</small>\r\n            <div class=\"chips\">\r\n              <span class=\"chip ${escapeHtml(role)}\">${escapeHtml(roleLabel(role))}</span>\r\n              ${removed ? `<span class=\"chip removed\">Removed</span>` : `<span class=\"chip\">Active</span>`}\r\n            </div>\r\n          </div>\r\n        </div>\r\n        <div class=\"row-actions\">\r\n          <button class=\"btn btn-light\" type=\"button\" onclick=\"window.location.href='#/teacher-profile.html?id=${escapeHtml(staff.uid)}'\"><i class=\"fas fa-id-card\"></i> View Profile</button>\r\n          <button class=\"btn btn-light\" type=\"button\" onclick=\"openEditStaff('${escapeHtml(staff.uid)}')\"><i class=\"fas fa-pen\"></i> Edit</button>\r\n          ${removed\r\n            ? `<button class=\"btn btn-success\" type=\"button\" onclick=\"setStaffRemoved('${escapeHtml(staff.uid)}', false)\"><i class=\"fas fa-user-check\"></i> Activate</button>`\r\n            : `<button class=\"btn btn-danger\" type=\"button\" onclick=\"setStaffRemoved('${escapeHtml(staff.uid)}', true)\"><i class=\"fas fa-user-slash\"></i> Remove</button>`}\r\n        </div>\r\n      </article>\r\n    `;\n  }).join(\"\");\n\n  $(\"staffPagination\").hidden = rows.length <= pageSize;\n  $(\"staffPaginationInfo\").textContent = `Showing ${start + 1}-${Math.min(start + pageSize, rows.length)} of ${rows.length} staff`;\n  $(\"staffPrevPage\").disabled = staffPage <= 1;\n  $(\"staffNextPage\").disabled = staffPage >= totalPages;\n}\n\r\nfunction renderSalaryStaffOptions() {\n  const activeStaff = staffRecords.filter((staff) => !isRemoved(staff));\r\n  $(\"salaryStaffSelect\").innerHTML = activeStaff.length\r\n    ? `<option value=\"\">Select staff</option>${activeStaff.map((staff) => `<option value=\"${escapeHtml(staff.uid)}\">${escapeHtml(staff.name || staff.email)} - ${escapeHtml(roleLabel(lower(staff.role)))}${staff.monthlySalary ? ` (Rs ${money(staff.monthlySalary).toLocaleString(\"en-IN\")})` : \"\"}</option>`).join(\"\")}`\r\n    : `<option value=\"\">No active staff found</option>`;\r\n}\n\nfunction salaryStatusClass(status, net, paid) {\n  const value = lower(status || salaryStatus(net, paid));\n  if (value.includes(\"paid\") && !value.includes(\"partial\")) return \"paid\";\n  if (value.includes(\"partial\")) return \"partial\";\n  return \"unpaid\";\n}\n\nfunction renderSalaryPlaceholder() {\n  $(\"activeSalaryHint\").className = \"salary-breakdown-card\";\n  $(\"activeSalaryHint\").innerHTML = `\n    <div class=\"salary-breakdown-head\">\n      <div>\n        <strong>Salary Breakdown</strong>\n        <span>Select a teacher or staff member to preview monthly salary details.</span>\n      </div>\n      <span class=\"salary-status-pill\">Ready</span>\n    </div>\n    <div class=\"salary-breakdown-grid\">\n      <div class=\"salary-breakdown-box base\"><span>Base Salary</span><strong>Rs 0</strong></div>\n      <div class=\"salary-breakdown-box\"><span>Net Salary</span><strong>Rs 0</strong></div>\n      <div class=\"salary-breakdown-box paid\"><span>Paid</span><strong>Rs 0</strong></div>\n      <div class=\"salary-breakdown-box due\"><span>Pending</span><strong>Rs 0</strong></div>\n    </div>\n    <div class=\"salary-breakdown-note\">Select a staff member to view salary, status, and payment history here.</div>\n  `;\n}\n\nfunction renderSalaryBreakdown(record = null, staff = null) {\n  const selectedStaff = staff || staffRecords.find((item) => item.uid === (record?.staffUid || record?.teacherUid || $(\"salaryStaffSelect\")?.value));\n  if (!record && !selectedStaff) {\n    renderSalaryPlaceholder();\n    return;\n  }\n  const base = money(record?.baseSalary ?? selectedStaff?.monthlySalary);\n  const net = money(record?.netSalary ?? base);\n  const paid = money(record?.paidAmount);\n  const due = money(record?.remainingAmount ?? Math.max(net - paid, 0));\n  const status = record?.status || salaryStatus(net, paid);\n  const staffName = record?.staffName || record?.teacherName || selectedStaff?.name || selectedStaff?.email || \"Selected Staff\";\n  const staffRole = record?.staffRole || selectedStaff?.role || \"staff\";\n  const staffId = record?.staffId || record?.teacherId || staffKey(selectedStaff) || \"-\";\n  const month = record?.monthLabel || monthLabel(record?.monthKey || $(\"salaryMonth\")?.value || currentMonth());\n  const session = record?.session || \"Current session\";\n  const payments = Array.isArray(record?.payments) ? record.payments.slice().reverse() : [];\n  $(\"activeSalaryHint\").className = \"salary-breakdown-card\";\n  $(\"activeSalaryHint\").innerHTML = `\n    <div class=\"salary-breakdown-head\">\n      <div>\n        <strong>${escapeHtml(staffName)}</strong>\n        <span>${escapeHtml(roleLabel(staffRole))} | ID: ${escapeHtml(staffId)} | ${escapeHtml(month)} | ${escapeHtml(session)}</span>\n      </div>\n      <span class=\"salary-status-pill ${salaryStatusClass(status, net, paid)}\">${escapeHtml(status)}</span>\n    </div>\n    <div class=\"salary-breakdown-grid\">\n      <div class=\"salary-breakdown-box base\"><span>Base Salary</span><strong>${moneyLabel(base)}</strong></div>\n      <div class=\"salary-breakdown-box\"><span>Net Salary</span><strong>${moneyLabel(net)}</strong></div>\n      <div class=\"salary-breakdown-box paid\"><span>Paid</span><strong>${moneyLabel(paid)}</strong></div>\n      <div class=\"salary-breakdown-box due\"><span>Pending</span><strong>${moneyLabel(due)}</strong></div>\n    </div>\n    <div class=\"salary-payment-history\">\n      <h4>Payment History</h4>\n      ${payments.length ? payments.map((payment) => `\n        <div class=\"salary-payment-item\">\n          <div><strong>${moneyLabel(payment.amount)}</strong><small>${escapeHtml(payment.note || payment.paymentMode || \"Salary payment\")}</small></div>\n          <span>${escapeHtml(payment.paymentDate ? new Date(`${payment.paymentDate}T00:00:00`).toLocaleDateString(\"en-IN\") : \"Date not set\")}</span>\n        </div>\n      `).join(\"\") : `<div class=\"salary-breakdown-note\">No payment history has been recorded for this salary yet.</div>`}\n    </div>\n    ${record ? \"\" : `<div class=\"salary-breakdown-note\">After the salary record is generated, paid and pending amounts will update here.</div>`}\n  `;\n}\n\nfunction renderSalaryRecords() {\n  $(\"salaryRecordsList\").removeAttribute(\"aria-busy\");\n  if ($(\"salaryRecordsList\").hidden || $(\"salaryRecordsList\").style.display === \"none\") return;\n  if (!salaryRecords.length) {\n    $(\"salaryRecordsList\").innerHTML = `<div class=\"empty\">No staff salary records yet.</div>`;\r\n    return;\r\n  }\r\n  $(\"salaryRecordsList\").innerHTML = salaryRecords\n    .slice()\n    .sort((a, b) => `${b.monthKey || \"\"}-${lower(b.staffName || b.teacherName)}`.localeCompare(`${a.monthKey || \"\"}-${lower(a.staffName || a.teacherName)}`))\n    .map((record) => {\r\n      const paid = money(record.paidAmount);\r\n      const net = money(record.netSalary);\r\n      const due = money(record.remainingAmount);\r\n      return `\r\n        <article class=\"salary-row\">\r\n          <div>\r\n            <strong>${escapeHtml(record.staffName || record.teacherName || \"Staff\")} - ${escapeHtml(record.monthLabel || monthLabel(record.monthKey))}</strong>\r\n            <small class=\"muted\">${escapeHtml(roleLabel(record.staffRole || record.role))} | Net Rs ${net.toLocaleString(\"en-IN\")} | Paid Rs ${paid.toLocaleString(\"en-IN\")} | Due Rs ${due.toLocaleString(\"en-IN\")} | ${escapeHtml(record.status || \"Unpaid\")}</small>\r\n          </div>\r\n          <button class=\"btn btn-light\" type=\"button\" onclick=\"selectSalaryRecord('${escapeHtml(record.id)}')\"><i class=\"fas fa-arrow-pointer\"></i> Select</button>\r\n        </article>\r\n      `;\r\n    }).join(\"\");\r\n}\r\n\r\nasync function loadSalaryRecords() {\n  if (!adminUID) return;\n  showSalaryLoader();\n  try {\n    const [teacherSnapshot, staffSnapshot] = await Promise.all([\n      getDocs(collection(db, \"schools\", adminUID, \"teacher_salary_records\")).catch(() => ({ docs: [] })),\n      getDocs(collection(db, \"schools\", adminUID, \"staff_salary_records\")).catch(() => ({ docs: [] }))\n    ]);\n    const recordsById = new Map();\n    teacherSnapshot.docs.forEach((item) => {\n      const data = item.data();\n      recordsById.set(`teacher:${item.id}`, {\n        id: item.id,\n        ...data,\n        staffUid: data.staffUid || data.teacherUid || \"\",\n        staffId: data.staffId || data.teacherId || \"\",\n        staffName: data.staffName || data.teacherName || \"Teacher\",\n        staffEmail: data.staffEmail || data.teacherEmail || \"\",\n        staffRole: \"teacher\",\n        sourceType: \"teacher_salary\",\n        salaryCollection: \"teacher_salary_records\"\n      });\n    });\n    staffSnapshot.docs.forEach((item) => {\n      const data = item.data();\n      const role = lower(data.staffRole || data.role);\n      const key = role === \"teacher\" ? `teacher:${item.id}` : `staff:${item.id}`;\n      if (recordsById.has(key)) return;\n      recordsById.set(key, {\n        id: item.id,\n        ...data,\n        staffRole: role || \"staff\",\n        sourceType: role === \"teacher\" ? \"teacher_salary\" : \"staff_salary\",\n        salaryCollection: role === \"teacher\" ? \"teacher_salary_records\" : \"staff_salary_records\"\n      });\n    });\n    salaryRecords = Array.from(recordsById.values());\n    renderSalaryRecords();\n    if ($(\"salaryStaffSelect\")?.value) previewSelectedStaffSalary();\n  } catch (error) {\n    console.warn(\"Unable to load staff salary records\", error);\n    $(\"salaryRecordsList\").removeAttribute(\"aria-busy\");\n    $(\"salaryRecordsList\").innerHTML = `<div class=\"empty\">Unable to load staff salary records.</div>`;\n  }\n}\n\r\nfunction setActiveSalaryRecord(record) {\n  activeSalaryRecord = record || null;\n  activeSalaryRecordId = record?.id || \"\";\n  $(\"recordSalaryBtn\").disabled = !record;\n  renderSalaryBreakdown(record);\n  $(\"paymentAmount\").value = record && record.remainingAmount > 0 ? record.remainingAmount : \"\";\n}\n\nfunction previewSelectedStaffSalary() {\n  const staff = staffRecords.find((item) => item.uid === $(\"salaryStaffSelect\").value);\n  const monthKey = $(\"salaryMonth\").value || currentMonth();\n  const existing = salaryRecords.find((record) => {\n    const uid = record.staffUid || record.teacherUid;\n    return uid === staff?.uid && (!record.monthKey || record.monthKey === monthKey);\n  });\n  if (existing) {\n    setActiveSalaryRecord(existing);\n    return;\n  }\n  activeSalaryRecord = null;\n  activeSalaryRecordId = \"\";\n  $(\"recordSalaryBtn\").disabled = true;\n  renderSalaryBreakdown(null, staff || null);\n}\n\r\nasync function ensureStaffSalaryRecord() {\n  const button = $(\"generateSalaryBtn\");\n  const staffUid = $(\"salaryStaffSelect\").value;\n  const monthKey = $(\"salaryMonth\").value;\n  const staff = staffRecords.find((item) => item.uid === staffUid);\n  if (!staff) return alert(\"Select staff first.\");\n  if (!monthKey) return alert(\"Select salary month first.\");\n  const role = lower(staff.role);\n  const salaryCollection = salaryCollectionForRole(role);\n  const baseSalary = money(staff.monthlySalary);\n  if (baseSalary <= 0 && !confirm(\"Monthly salary is 0. Generate salary record anyway?\")) return null;\n  setStaffBusy(button, true, `<i class=\"fas fa-spinner fa-spin\"></i> Generating...`);\n  $(\"activeSalaryHint\").innerHTML = `<div class=\"staff-inline-loader\"><i class=\"fas fa-spinner fa-spin\"></i> Preparing salary record...</div>`;\n  try {\n    const recordId = `${staffUid}_${monthKey}`;\n    const recordRef = doc(db, \"schools\", adminUID, salaryCollection, recordId);\n    const existingSnap = await getDoc(recordRef);\n    const existing = existingSnap.exists() ? existingSnap.data() : {};\n    let salarySessionId = existing.sessionId || \"\";\n    let salarySessionLabel = existing.session || \"\";\n    if (!salarySessionId) {\n      try {\n        let viewSessionId = \"\";\n        try { viewSessionId = localStorage.getItem(\"schoolix.viewSessionId\") || \"\"; } catch (_) {}\n        const activeSnap = await getDoc(doc(db, \"schools\", adminUID, \"settings\", \"activeSession\"));\n        salarySessionId = viewSessionId || (activeSnap.exists() ? activeSnap.data().sessionId || \"\" : \"\");\n        if (salarySessionId) {\n          const sessionSnap = await getDoc(doc(db, \"schools\", adminUID, \"sessions\", salarySessionId));\n          if (sessionSnap.exists()) {\n            const sessionData = sessionSnap.data();\n            salarySessionLabel = sessionData.session || sessionData.name || salarySessionId;\n          }\n        }\n      } catch (error) {\n        console.warn(\"Unable to attach session to salary record\", error);\n      }\n    }\n    const payments = Array.isArray(existing.payments) ? existing.payments : [];\n    const paidAmount = money(payments.reduce((sum, payment) => sum + Number(payment.amount || 0), 0));\n    const netSalary = money(existing.netSalary ?? baseSalary);\n    const remainingAmount = money(Math.max(netSalary - paidAmount, 0));\n    const payload = {\n      staffUid,\n      staffId: staffKey(staff),\n      staffName: staff.name || staff.email || \"Staff\",\n      staffEmail: staff.email || \"\",\n      staffRole: role,\n      designation: staffDesignation(staff),\n      department: staff.department || \"\",\n      monthKey,\n      monthLabel: monthLabel(monthKey),\n      sessionId: salarySessionId,\n      session: salarySessionLabel,\n      baseSalary,\n      netSalary,\n      paidAmount,\n      remainingAmount,\n      status: salaryStatus(netSalary, paidAmount),\n      payments,\n      sourceType: role === \"teacher\" ? \"teacher_salary\" : \"staff_salary\",\n      updatedAt: serverTimestamp(),\n      updatedBy: auth.currentUser?.email || \"admin\"\n    };\n    if (role === \"teacher\") {\n      payload.teacherUid = staffUid;\n      payload.teacherId = staff.teacherId || staffKey(staff);\n      payload.teacherName = staff.name || staff.email || \"Teacher\";\n      payload.teacherEmail = staff.email || \"\";\n    }\n    if (!existingSnap.exists()) payload.generatedAt = serverTimestamp();\n    await setDoc(recordRef, payload, { merge: true });\n    const record = { id: recordId, ...payload, salaryCollection };\n    activeSalaryRecordId = recordId;\n    activeSalaryRecord = record;\n    await loadSalaryRecords();\n    setActiveSalaryRecord(salaryRecords.find((item) => item.id === recordId) || record);\n    return activeSalaryRecord;\n  } finally {\n    setStaffBusy(button, false);\n  }\n}\n\r\nasync function recordStaffSalaryPayment(event) {\n  event.preventDefault();\n  const button = $(\"recordSalaryBtn\");\n  if (!activeSalaryRecordId || !activeSalaryRecord) return alert(\"Generate or select salary record first.\");\n  const amount = money($(\"paymentAmount\").value);\n  if (amount <= 0 || !$(\"paymentDate\").value) return alert(\"Enter payment amount and payment date.\");\n  setStaffBusy(button, true, `<i class=\"fas fa-spinner fa-spin\"></i> Recording...`);\n  try {\n    const salaryCollection = salaryCollectionForRecord(activeSalaryRecord);\n    const recordRef = doc(db, \"schools\", adminUID, salaryCollection, activeSalaryRecordId);\n    const snap = await getDoc(recordRef);\n    if (!snap.exists()) return alert(\"Salary record no longer exists.\");\n    const record = {\n      id: snap.id,\n      ...snap.data(),\n      sourceType: salaryCollection === \"teacher_salary_records\" ? \"teacher_salary\" : \"staff_salary\",\n      salaryCollection\n    };\n    const payments = Array.isArray(record.payments) ? [...record.payments] : [];\n    const payment = {\n      amount,\n      paymentDate: $(\"paymentDate\").value,\n      paymentMode: $(\"paymentMode\").value,\n      note: clean($(\"paymentNote\").value),\n      recordedBy: auth.currentUser?.email || \"admin\",\n      recordedAt: new Date().toISOString(),\n      ledgerTransactionId: newLedgerTransactionId(\"SAL\")\n    };\n    payments.push(payment);\n    const paidAmount = money(payments.reduce((sum, item) => sum + Number(item.amount || 0), 0));\n    const remainingAmount = money(Math.max(Number(record.netSalary || 0) - paidAmount, 0));\n    await setDoc(recordRef, {\n      payments,\n      paidAmount,\n      remainingAmount,\n      status: salaryStatus(Number(record.netSalary || 0), paidAmount),\n      updatedAt: serverTimestamp(),\n      updatedBy: auth.currentUser?.email || \"admin\"\n    }, { merge: true });\n    await syncStaffSalaryDebit({\n      db,\n      schoolId: adminUID,\n      actor: { uid: auth.currentUser.uid, email: auth.currentUser.email, role: \"admin\" },\n      recordId: activeSalaryRecordId,\n      record,\n      payment,\n      paymentIndex: payments.length - 1\n    });\n    $(\"paymentAmount\").value = \"\";\n    $(\"paymentNote\").value = \"\";\n    await loadSalaryRecords();\n    setActiveSalaryRecord(salaryRecords.find((item) => item.id === activeSalaryRecordId) || null);\n    alert(\"Salary payment recorded and debited in School Accounts.\");\n  } finally {\n    setStaffBusy(button, false);\n  }\n}\n\r\nasync function loadStaff() {\n  if (!adminUID) return;\n  showStaffListLoader();\n  showSalaryLoader(\"Waiting for staff records...\");\n  $(\"salaryStaffSelect\").innerHTML = `<option value=\"\">Loading staff...</option>`;\n  try {\n    const [adminSnap, schoolSnap] = await Promise.all([\r\n      getDocs(query(collection(db, \"users\"), where(\"adminId\", \"==\", adminUID))),\r\n      getDocs(query(collection(db, \"users\"), where(\"schoolId\", \"==\", adminUID)))\r\n    ]);\r\n    const seen = new Set();\r\n    staffRecords = [];\r\n    [...adminSnap.docs, ...schoolSnap.docs].forEach((docSnap) => {\r\n      if (seen.has(docSnap.id)) return;\r\n      seen.add(docSnap.id);\r\n      const data = docSnap.data();\r\n      if (!staffRoles.includes(lower(data.role))) return;\r\n      staffRecords.push({ uid: docSnap.id, ...data });\r\n    });\r\n    renderSalaryStaffOptions();\r\n    renderStaff();\r\n    await loadSalaryRecords();\r\n  } catch (error) {\n    console.error(\"Staff load failed:\", error);\n    $(\"staffList\").removeAttribute(\"aria-busy\");\n    $(\"salaryRecordsList\").removeAttribute(\"aria-busy\");\n    $(\"staffList\").innerHTML = `<div class=\"empty\">Unable to load staff: ${escapeHtml(error.message)}</div>`;\n    $(\"salaryStaffSelect\").innerHTML = `<option value=\"\">Unable to load staff</option>`;\n  }\n}\n\r\nasync function createStaff(event) {\r\n  event.preventDefault();\r\n  const role = $(\"staffRole\").value;\r\n  const name = clean($(\"staffName\").value);\r\n  const email = lower($(\"staffEmail\").value);\r\n  const password = $(\"staffPassword\").value;\r\n  const needsLogin = role !== \"staff\";\r\n  const button = $(\"createStaffBtn\");\r\n  const original = button.innerHTML;\r\n  if (!role || !name) {\r\n    alert(\"Please fill role and name.\");\r\n    return;\r\n  }\r\n  if (needsLogin && (!email || password.length < 6)) {\r\n    alert(\"Please fill email and minimum 6 character password for portal login.\");\r\n    return;\r\n  }\r\n  if (role === \"teacher\" && (!clean($(\"teacherClass\").value) || !clean($(\"teacherSection\").value))) {\r\n    alert(\"Please enter class and section for teacher accounts.\");\r\n    return;\r\n  }\r\n  if (role === \"staff\" && !clean($(\"staffDesignation\").value)) {\r\n    alert(\"Please tell who this Other Staff is, for example Receptionist, Guard, Driver, Clerk.\");\r\n    return;\r\n  }\r\n\r\n  try {\r\n    button.disabled = true;\r\n    button.innerHTML = `<i class=\"fas fa-spinner fa-spin\"></i> Creating...`;\r\n    const userRef = needsLogin ? null : doc(collection(db, \"users\"));\r\n    const userCred = needsLogin ? await createUserWithEmailAndPassword(staffCreatorAuth, email, password) : null;\r\n    const uid = needsLogin ? userCred.user.uid : userRef.id;\r\n    const generatedId = await generateStaffId(role);\r\n    const base = {\r\n      name,\r\n      email,\r\n      role,\r\n      adminId: adminUID,\r\n      schoolId: adminUID,\r\n      loginEnabled: needsLogin,\r\n      portalAccess: needsLogin,\r\n      staffLocalOnly: !needsLogin,\r\n      active: true,\r\n      panelStatus: \"active\",\r\n      createdAt: serverTimestamp(),\r\n      updatedAt: serverTimestamp()\r\n    };\r\n    const roleFields = role === \"teacher\"\r\n      ? {\r\n          teacherId: generatedId,\r\n          class: clean($(\"teacherClass\").value),\r\n          section: clean($(\"teacherSection\").value),\r\n          subject: clean($(\"teacherSubject\").value),\r\n          monthlySalary: money($(\"staffSalary\").value)\r\n        }\r\n      : {\r\n          staffId: generatedId,\r\n          designation: role === \"staff\" ? clean($(\"staffDesignation\").value) : roleLabel(role),\r\n          department: clean($(\"staffDepartment\").value),\r\n          monthlySalary: money($(\"staffSalary\").value)\r\n        };\r\n\r\n    await setDoc(needsLogin ? doc(db, \"users\", uid) : userRef, { ...base, ...roleFields });\r\n    if (role === \"teacher\") {\r\n      await setDoc(doc(db, \"schools\", adminUID, \"teacher_salaries\", uid), {\r\n        teacherUid: uid,\r\n        teacherId: generatedId,\r\n        teacherName: name,\r\n        teacherEmail: email,\r\n        monthlySalary: money($(\"staffSalary\").value),\r\n        adminId: adminUID,\r\n        schoolId: adminUID,\r\n        createdAt: serverTimestamp(),\r\n        updatedAt: serverTimestamp()\r\n      }, { merge: true });\r\n    }\r\n    $(\"staffForm\").reset();\n    $(\"staffRole\").value = \"teacher\";\r\n    toggleTeacherFields();\r\n    alert(needsLogin ? `${roleLabel(role)} account created successfully.` : `${roleLabel(role)} details saved without login access.`);\r\n    await loadStaff();\r\n  } catch (error) {\r\n    alert(error.message || \"Unable to create staff account.\");\r\n  } finally {\r\n    button.disabled = false;\r\n    button.innerHTML = original;\r\n  }\r\n}\r\n\r\nfunction toggleTeacherFields() {\r\n  const role = $(\"staffRole\").value;\r\n  const isOtherStaff = role === \"staff\";\r\n  $(\"teacherFields\").classList.toggle(\"show\", role === \"teacher\");\r\n  $(\"otherFields\").classList.toggle(\"show\", isOtherStaff);\r\n  $(\"staffEmailField\").classList.toggle(\"is-hidden\", isOtherStaff);\r\n  $(\"staffPasswordField\").classList.toggle(\"is-hidden\", isOtherStaff);\r\n  $(\"staffEmail\").required = !isOtherStaff;\r\n  $(\"staffPassword\").required = !isOtherStaff;\r\n  $(\"staffDesignation\").required = isOtherStaff;\r\n  if (isOtherStaff) {\r\n    $(\"staffEmail\").value = \"\";\r\n    $(\"staffPassword\").value = \"\";\r\n    $(\"createStaffBtn\").innerHTML = `<i class=\"fas fa-user-plus\"></i> Save Staff Details`;\r\n  } else {\r\n    $(\"createStaffBtn\").innerHTML = `<i class=\"fas fa-user-plus\"></i> Create Staff Account`;\r\n  }\r\n}\r\n\r\nfunction openEditStaff(uid) {\r\n  const staff = staffRecords.find((item) => item.uid === uid);\r\n  if (!staff) return alert(\"Staff record not found.\");\r\n  $(\"editUid\").value = uid;\r\n  $(\"editName\").value = staff.name || \"\";\r\n  $(\"editEmail\").value = staff.email || \"\";\r\n  $(\"editRole\").value = lower(staff.role) || \"staff\";\r\n  $(\"editStaffId\").value = staffKey(staff);\r\n  $(\"editClass\").value = staff.class || \"\";\r\n  $(\"editSection\").value = staff.section || \"\";\r\n  $(\"editSubject\").value = staff.subject || \"\";\r\n  $(\"editSalary\").value = staff.monthlySalary || \"\";\r\n  $(\"editDesignation\").value = staff.designation || \"\";\r\n  $(\"editDepartment\").value = staff.department || \"\";\r\n  $(\"editDialog\").classList.add(\"show\");\r\n  $(\"editDialog\").setAttribute(\"aria-hidden\", \"false\");\r\n}\r\n\r\nfunction closeEditDialog() {\r\n  $(\"editDialog\").classList.remove(\"show\");\r\n  $(\"editDialog\").setAttribute(\"aria-hidden\", \"true\");\r\n}\r\n\r\nasync function saveStaff(event) {\n  event.preventDefault();\n  const button = event.submitter || $(\"editForm\").querySelector('button[type=\"submit\"]');\n  const uid = $(\"editUid\").value;\n  const role = $(\"editRole\").value;\r\n  const staffId = clean($(\"editStaffId\").value);\r\n  if (!uid) return;\r\n  const payload = {\r\n    name: clean($(\"editName\").value),\r\n    email: lower($(\"editEmail\").value),\r\n    role,\r\n    class: clean($(\"editClass\").value),\r\n    section: clean($(\"editSection\").value),\r\n    subject: clean($(\"editSubject\").value),\r\n    designation: clean($(\"editDesignation\").value),\r\n    department: clean($(\"editDepartment\").value),\r\n    monthlySalary: money($(\"editSalary\").value),\r\n    updatedAt: serverTimestamp()\r\n  };\r\n  if (role === \"teacher\") payload.teacherId = staffId;\n  else payload.staffId = staffId;\n  setStaffBusy(button, true, `<i class=\"fas fa-spinner fa-spin\"></i> Saving...`);\n  try {\n    await setDoc(doc(db, \"users\", uid), payload, { merge: true });\n    if (role === \"teacher\") {\n      await setDoc(doc(db, \"schools\", adminUID, \"teacher_salaries\", uid), {\n        teacherUid: uid,\n        teacherId: staffId,\n        teacherName: payload.name,\n        teacherEmail: payload.email,\n        monthlySalary: payload.monthlySalary,\n        adminId: adminUID,\n        schoolId: adminUID,\n        updatedAt: serverTimestamp()\n      }, { merge: true });\n    }\n    closeEditDialog();\n    await loadStaff();\n    alert(\"Staff details updated.\");\n  } finally {\n    setStaffBusy(button, false);\n  }\n}\n\r\nfunction selectSalaryRecord(recordId) {\n  const record = salaryRecords.find((item) => item.id === recordId);\n  if (!record) return alert(\"Salary record not found.\");\n  $(\"salaryStaffSelect\").value = record.staffUid || record.teacherUid || \"\";\n  $(\"salaryMonth\").value = record.monthKey || currentMonth();\n  setActiveSalaryRecord(record);\n}\n\r\nasync function setStaffRemoved(uid, removed) {\n  const staff = staffRecords.find((item) => item.uid === uid);\n  if (!staff) return alert(\"Staff record not found.\");\n  const action = removed ? \"remove from active staff\" : \"activate\";\n  if (!confirm(`${action.charAt(0).toUpperCase() + action.slice(1)} ${staff.name || staff.email}?`)) return;\n  const button = document.activeElement?.tagName === \"BUTTON\" ? document.activeElement : null;\n  setStaffBusy(button, true, `<i class=\"fas fa-spinner fa-spin\"></i> ${removed ? \"Removing...\" : \"Activating...\"}`);\n  try {\n    await setDoc(doc(db, \"users\", uid), {\n      active: !removed,\n      removedFromPanel: removed,\n      panelStatus: removed ? \"removed\" : \"active\",\n      removedAt: removed ? serverTimestamp() : null,\n      removedBy: removed ? (auth.currentUser?.email || \"admin\") : \"\",\n      updatedAt: serverTimestamp()\n    }, { merge: true });\n    if (lower(staff.role) === \"teacher\") {\n      await setDoc(doc(db, \"schools\", adminUID, \"teacher_salaries\", uid), {\n        removedFromPanel: removed,\n        panelStatus: removed ? \"removed\" : \"active\",\n        updatedAt: serverTimestamp()\n      }, { merge: true });\n    }\n    await loadStaff();\n  } finally {\n    setStaffBusy(button, false);\n  }\n}\n\r\nonAuthStateChanged(auth, async (user) => {\n  showStaffListLoader(\"Checking admin access...\");\n  showSalaryLoader(\"Preparing salary desk...\");\n  if (!user) {\n    window.location.href = \"#/index.html\";\n    return;\n  }\n  try {\n    const userDoc = await getDoc(doc(db, \"users\", user.uid));\n    const role = lower(userDoc.exists() ? userDoc.data().role : \"\");\n    if (!userDoc.exists() || role !== \"admin\") {\n      alert(\"Access denied. Only admin can manage staff.\");\n      window.location.href = \"#/index.html\";\n      return;\n    }\n    adminUID = user.uid;\n    await loadStaff();\n  } catch (error) {\n    console.error(\"Staff management auth failed:\", error);\n    $(\"staffList\").removeAttribute(\"aria-busy\");\n    $(\"salaryRecordsList\").removeAttribute(\"aria-busy\");\n    $(\"staffList\").innerHTML = `<div class=\"empty\">Unable to open staff management.</div>`;\n    $(\"salaryRecordsList\").innerHTML = `<div class=\"empty\">Salary desk unavailable.</div>`;\n  }\n});\n\r\n$(\"staffForm\").addEventListener(\"submit\", createStaff);\r\n$(\"staffRole\").addEventListener(\"change\", toggleTeacherFields);\r\n$(\"staffSearch\").addEventListener(\"input\", () => { resetStaffPage(); renderStaff(); });\n$(\"roleFilter\").addEventListener(\"change\", () => { resetStaffPage(); renderStaff(); });\n$(\"statusFilter\").addEventListener(\"change\", () => { resetStaffPage(); renderStaff(); });\n$(\"staffPageSize\").addEventListener(\"change\", () => { resetStaffPage(); renderStaff(); });\n$(\"staffPrevPage\").addEventListener(\"click\", () => { staffPage = Math.max(1, staffPage - 1); renderStaff(); });\n$(\"staffNextPage\").addEventListener(\"click\", () => { staffPage += 1; renderStaff(); });\n$(\"salaryStaffSelect\").addEventListener(\"change\", previewSelectedStaffSalary);\n$(\"salaryMonth\").addEventListener(\"change\", previewSelectedStaffSalary);\n$(\"editForm\").addEventListener(\"submit\", saveStaff);\n$(\"generateSalaryBtn\").addEventListener(\"click\", () => ensureStaffSalaryRecord().catch((error) => alert(error.message || \"Unable to generate salary record.\")));\r\n$(\"salaryForm\").addEventListener(\"submit\", (event) => recordStaffSalaryPayment(event).catch((error) => alert(error.message || \"Unable to record salary payment.\")));\r\n$(\"closeEditBtn\").addEventListener(\"click\", closeEditDialog);\r\n$(\"cancelEditBtn\").addEventListener(\"click\", closeEditDialog);\r\n$(\"editDialog\").addEventListener(\"click\", (event) => {\r\n  if (event.target === $(\"editDialog\")) closeEditDialog();\r\n});\r\nwindow.openEditStaff = openEditStaff;\r\nwindow.setStaffRemoved = setStaffRemoved;\r\nwindow.selectSalaryRecord = selectSalaryRecord;\r\n$(\"salaryMonth\").value = currentMonth();\n$(\"paymentDate\").value = todayISO();\ntoggleTeacherFields();\nrenderSalaryPlaceholder();\nshowStaffListLoader(\"Loading staff management...\");\nshowSalaryLoader(\"Loading salary desk...\");\n</script>\n<script type=\"module\" src=\"access-control.js?v=accountant-guard-20260806-3\"></script>\n<script src=\"schoolix-polish.js\" defer></script>\n<script src=\"admin-shell.js?v=staff-loaders-20260806\" defer></script>\n","styles":[{"tag":"style","attributes":{"id":"sxCriticalLoaderStyle"},"text":"\nhtml.sx-page-loading,\nhtml.sx-page-loading body {\n  min-height: 100%;\n  background: #f8fafc !important;\n}\nhtml.sx-page-loading body::before,\nhtml.sx-page-loading body::after {\n  visibility: hidden !important;\n}\nhtml.sx-page-loading body > :not(#sxPageLoader):not(script):not(style) {\n  visibility: hidden !important;\n}\n.sx-page-loader {\n  position: fixed;\n  inset: 0;\n  z-index: 2147482500;\n  display: flex;\n  align-items: stretch;\n  justify-content: stretch;\n  background: #f8fafc;\n  transition: opacity 0.25s cubic-bezier(0.4, 0, 0.2, 1), visibility 0.25s ease;\n  overflow: hidden;\n}\n.sx-page-loader.is-hidden {\n  opacity: 0;\n  visibility: hidden;\n  pointer-events: none;\n}\n.sx-page-loader .dots-container {\n  position: fixed;\n  inset: 0;\n  display: block;\n  width: 100vw;\n  height: 100vh;\n  padding: 0;\n  margin: 0;\n  overflow: hidden;\n  background: #f8fafc;\n}\n.sx-page-loader .dots-container::before,\n.sx-page-loader .dots-container::after,\n.sx-page-loader .dot {\n  display: none !important;\n}\n"},{"tag":"link","attributes":{"rel":"stylesheet","href":"schoolix-polish.css"},"text":"\n<link rel=\"stylesheet\" href=\"admin-shell.css?v=navbar-20260721\">\n<style id=\"staffProfessionalOverrides\">\nbody.sx-admin-app {\n  background: #f3f6fb;\n  color: #0f172a;\n  font-family: \"DM Sans\", \"Inter\", \"Segoe UI\", Arial, sans-serif;\n}\nbody.sx-admin-app .staff-page,\nbody.sx-admin-app .staff-page input,\nbody.sx-admin-app .staff-page select,\nbody.sx-admin-app .staff-page button {\n  font-family: \"DM Sans\", \"Inter\", \"Segoe UI\", Arial, sans-serif;\n}\nbody.sx-admin-app .staff-page h1,\nbody.sx-admin-app .staff-page h2,\nbody.sx-admin-app .staff-page .stat strong,\nbody.sx-admin-app .staff-page .staff-main strong {\n  font-family: \"Sora\", \"DM Sans\", \"Inter\", sans-serif;\n}\nbody.sx-admin-app .staff-page {\n  width: min(1220px, calc(100% - 40px));\n  margin: 0 auto;\n  padding: 26px 0 46px;\n}\nbody.sx-admin-app .hero,\nbody.sx-admin-app .panel,\nbody.sx-admin-app .stat,\nbody.sx-admin-app .staff-row,\nbody.sx-admin-app .salary-row {\n  border-radius: 8px;\n  letter-spacing: 0;\n}\n"}],"scripts":[{"attributes":{"id":"sxCriticalLoaderScript"},"text":"\r\n(function () {\r\n  var root = document.documentElement;\r\n  root.classList.add(\"sx-page-loading\");\r\n  window.SchoolixPageLoaderEarly = window.SchoolixPageLoaderEarly || { startedAt: Date.now() };\r\n\r\n  function markEarlyReady(reason) {\r\n    window.SchoolixPageLoaderEarly.ready = true;\r\n    window.SchoolixPageLoaderEarly.reason = reason || \"dom-ready\";\r\n    try {\r\n      window.dispatchEvent(new CustomEvent(\"schoolix:critical-load-ready\", { detail: window.SchoolixPageLoaderEarly }));\r\n    } catch (_) {}\r\n  }\r\n\r\n  function afterFirstPaint(reason) {\r\n    requestAnimationFrame(function () {\r\n      requestAnimationFrame(function () { markEarlyReady(reason); });\r\n    });\r\n  }\r\n\r\n  function emergencyHide() {\r\n    if (window.SchoolixPageLoader || !root.classList.contains(\"sx-page-loading\")) return;\r\n    root.classList.remove(\"sx-page-loading\");\r\n    root.classList.add(\"sx-page-loaded\");\r\n    var loader = document.getElementById(\"sxPageLoader\");\r\n    if (!loader) return;\r\n    loader.classList.add(\"is-hidden\");\r\n    setTimeout(function () { loader.remove(); }, 260);\r\n  }\r\n\r\n  if (document.readyState === \"loading\") {\r\n    document.addEventListener(\"DOMContentLoaded\", function () { afterFirstPaint(\"dom-ready\"); }, { once: true });\r\n  } else {\r\n    afterFirstPaint(document.readyState === \"complete\" ? \"document-complete\" : \"dom-ready\");\r\n  }\r\n  window.addEventListener(\"load\", function () { markEarlyReady(\"window-load\"); }, { once: true });\r\n  setTimeout(emergencyHide, 3200);\r\n}());\r\n"},{"attributes":{"src":"school-branding.js"},"text":""},{"attributes":{},"text":"\n(function () {\n  function escapeLoaderText(value) {\n    return String(value || \"\").replace(/[&<>\"']/g, function (char) {\n      return ({ \"&\": \"&amp;\", \"<\": \"&lt;\", \">\": \"&gt;\", '\"': \"&quot;\", \"'\": \"&#39;\" })[char];\n    });\n  }\n  function skeletonRows(count) {\n    var rows = \"\";\n    for (var i = 0; i < count; i += 1) {\n      rows += '<div class=\"staff-skeleton\"><div class=\"staff-skeleton-line title\"></div><div class=\"staff-skeleton-line meta\"></div><div class=\"staff-skeleton-line short\"></div></div>';\n    }\n    return '<div class=\"staff-loader\" aria-hidden=\"true\">' + rows + \"</div>\";\n  }\n  function setLoader(id, message, count) {\n    var list = document.getElementById(id);\n    if (!list) return;\n    if (list.hidden || list.style.display === \"none\") return;\n    list.setAttribute(\"aria-busy\", \"true\");\n    list.innerHTML = '<div class=\"staff-inline-loader\"><i class=\"fas fa-spinner fa-spin\"></i>' + escapeLoaderText(message) + \"</div>\" + skeletonRows(count);\n  }\n  function setFallback(id, message) {\n    var list = document.getElementById(id);\n    if (!list || list.getAttribute(\"aria-busy\") !== \"true\") return;\n    if (list.hidden || list.style.display === \"none\") return;\n    list.removeAttribute(\"aria-busy\");\n    list.innerHTML = '<div class=\"empty\">' + escapeLoaderText(message) + \"</div>\";\n  }\n  window.SchoolixStaffManagementLoading = {\n    staff: function (message) { setLoader(\"staffList\", message || \"Loading staff management...\", 5); },\n    salary: function (message) { setLoader(\"salaryRecordsList\", message || \"Loading salary desk...\", 3); },\n    fallback: function () {\n      setFallback(\"staffList\", \"Staff data could not be loaded. Please refresh or sign in again.\");\n      setFallback(\"salaryRecordsList\", \"Salary desk could not be loaded.\");\n    }\n  };\n  window.SchoolixStaffManagementLoading.staff();\n  window.SchoolixStaffManagementLoading.salary();\n  window.setTimeout(function () {\n    if (!window.SchoolixStaffManagementModuleLoaded) window.SchoolixStaffManagementLoading.fallback();\n  }, 18000);\n}());\n"},{"attributes":{"type":"module"},"text":"\nimport { initializeApp } from \"./firebase-compat.js?v=staff-loaders-20260806\";\nimport {\r\n  getAuth,\r\n  createUserWithEmailAndPassword,\r\n  onAuthStateChanged,\r\n  signOut\r\n} from \"./firebase-compat.js?v=staff-loaders-20260806\";\nimport {\r\n  getFirestore,\r\n  doc,\r\n  setDoc,\r\n  getDoc,\r\n  getDocs,\r\n  collection,\r\n  serverTimestamp,\r\n  query,\r\n  where\r\n} from \"./firebase-compat.js?v=staff-loaders-20260806\";\nimport { newLedgerTransactionId, syncStaffSalaryDebit } from \"./accounts-ledger.js?v=staff-loaders-20260806\";\n\nwindow.SchoolixStaffManagementModuleLoaded = true;\n\nconst firebaseConfig = {\n  apiKey: \"AIzaSyAomGwef93HFT9Xyx7SVW95FPw_IcIAICE\",\r\n  authDomain: \"schoolix-48107.firebaseapp.com\",\r\n  projectId: \"schoolix-48107\",\r\n  storageBucket: \"schoolix-48107.firebasestorage.app\",\r\n  messagingSenderId: \"133937954491\",\r\n  appId: \"1:133937954491:web:69d8064422617eb8c4339e\"\r\n};\r\n\r\nconst app = initializeApp(firebaseConfig);\r\nconst auth = getAuth(app);\r\nconst db = getFirestore(app);\r\nconst staffCreatorApp = initializeApp(firebaseConfig, \"staffManagementCreatorApp\");\r\nconst staffCreatorAuth = getAuth(staffCreatorApp);\r\nconst staffRoles = [\"teacher\", \"librarian\", \"accountant\", \"staff\"];\r\nlet adminUID = \"\";\r\nlet staffRecords = [];\nlet salaryRecords = [];\nlet activeSalaryRecordId = \"\";\nlet activeSalaryRecord = null;\nlet staffPage = 1;\n\r\nconst $ = (id) => document.getElementById(id);\r\nconst clean = (value) => String(value || \"\").replace(/\\s+/g, \" \").trim();\r\nconst lower = (value) => clean(value).toLowerCase();\r\nconst money = (value) => Number.isFinite(Number(value)) ? Number(value) : 0;\r\nconst roleLabel = (role) => ({ teacher: \"Teacher\", librarian: \"Librarian\", accountant: \"Accountant\", staff: \"Other Staff\" }[role] || clean(role) || \"Staff\");\r\nconst isRemoved = (staff) => staff.removedFromPanel === true || staff.panelStatus === \"removed\" || staff.active === false;\r\nconst todayISO = () => new Date().toISOString().slice(0, 10);\r\nconst currentMonth = () => todayISO().slice(0, 7);\nconst monthLabel = (value) => value ? new Date(`${value}-01T12:00:00`).toLocaleDateString(\"en-IN\", { month: \"long\", year: \"numeric\" }) : \"Salary\";\nconst salaryStatus = (net, paid) => paid <= 0 ? \"Unpaid\" : paid >= net ? \"Paid\" : \"Partially Paid\";\nconst moneyLabel = (value) => `Rs ${money(value).toLocaleString(\"en-IN\")}`;\n\nfunction staffSkeletonRows(count = 4) {\n  return `<div class=\"staff-loader\" aria-hidden=\"true\">${Array.from({ length: count }).map(() => `\n    <div class=\"staff-skeleton\">\n      <div class=\"staff-skeleton-line title\"></div>\n      <div class=\"staff-skeleton-line meta\"></div>\n      <div class=\"staff-skeleton-line short\"></div>\n    </div>\n  `).join(\"\")}</div>`;\n}\n\nfunction setStaffBusy(element, busy, busyHtml = \"\") {\n  if (!element) return;\n  if (busy) {\n    element.dataset.originalHtml = element.dataset.originalHtml || element.innerHTML;\n    element.disabled = true;\n    element.setAttribute(\"aria-busy\", \"true\");\n    if (busyHtml) element.innerHTML = busyHtml;\n    return;\n  }\n  element.disabled = false;\n  element.removeAttribute(\"aria-busy\");\n  if (element.dataset.originalHtml) {\n    element.innerHTML = element.dataset.originalHtml;\n    delete element.dataset.originalHtml;\n  }\n}\n\nfunction showStaffListLoader(message = \"Loading staff records...\") {\n  const list = $(\"staffList\");\n  if (!list) return;\n  list.setAttribute(\"aria-busy\", \"true\");\n  list.innerHTML = `<div class=\"staff-inline-loader\"><i class=\"fas fa-spinner fa-spin\"></i>${escapeHtml(message)}</div>${staffSkeletonRows(5)}`;\n  $(\"staffPagination\").hidden = true;\n}\n\nfunction showSalaryLoader(message = \"Loading salary records...\") {\n  const list = $(\"salaryRecordsList\");\n  if (!list) return;\n  if (list.hidden || list.style.display === \"none\") return;\n  list.setAttribute(\"aria-busy\", \"true\");\n  list.innerHTML = `<div class=\"staff-inline-loader\"><i class=\"fas fa-spinner fa-spin\"></i>${escapeHtml(message)}</div>${staffSkeletonRows(3)}`;\n}\n\nfunction escapeHtml(value) {\n  return String(value || \"\")\n    .replace(/&/g, \"&amp;\")\r\n    .replace(/</g, \"&lt;\")\r\n    .replace(/>/g, \"&gt;\")\r\n    .replace(/\"/g, \"&quot;\")\r\n    .replace(/'/g, \"&#39;\");\r\n}\r\n\r\nfunction initials(name, fallback = \"S\") {\r\n  const words = clean(name).split(\" \").filter(Boolean);\r\n  return (words.length ? words.slice(0, 2).map((word) => word[0]).join(\"\") : fallback).toUpperCase();\r\n}\r\n\r\nfunction staffKey(staff = {}) {\r\n  return clean(staff.teacherId || staff.staffId || staff.employeeId || staff.uid || \"\");\r\n}\r\n\r\nfunction staffDesignation(staff = {}) {\n  const role = lower(staff.role);\n  if (role === \"teacher\") return staff.subject || \"Teacher\";\n  if (role === \"librarian\") return \"Librarian\";\n  if (role === \"accountant\") return \"Accountant\";\n  return staff.designation || staff.department || \"Other Staff\";\n}\n\nfunction salaryCollectionForRole(role = \"\") {\n  return lower(role) === \"teacher\" ? \"teacher_salary_records\" : \"staff_salary_records\";\n}\n\nfunction salaryCollectionForRecord(record = {}) {\n  return record.salaryCollection || (lower(record.staffRole || record.role) === \"teacher\" || record.sourceType === \"teacher_salary\"\n    ? \"teacher_salary_records\"\n    : \"staff_salary_records\");\n}\n\r\nasync function generateStaffId(role) {\n  const prefix = role === \"teacher\" ? \"TCH\" : role === \"librarian\" ? \"LIB\" : role === \"accountant\" ? \"ACC\" : \"STF\";\n  const existing = new Set(staffRecords.map((staff) => staffKey(staff)).filter(Boolean).map((id) => id.toUpperCase()));\n  const nextNumber = staffRecords.reduce((max, staff) => {\n    const id = staffKey(staff).toUpperCase();\n    const match = id.match(new RegExp(`^${prefix}-?(\\\\d+)$`));\n    return match ? Math.max(max, Number(match[1]) || 0) : max;\n  }, 0) + 1;\n  let number = nextNumber;\n  let id = \"\";\n  do {\n    id = `${prefix}-${String(number).padStart(3, \"0\")}`;\n    number += 1;\n  } while (existing.has(id));\n  return id;\n}\n\r\nfunction setStats() {\r\n  const activeStaff = staffRecords.filter((staff) => !isRemoved(staff));\r\n  $(\"statTotal\").textContent = activeStaff.length.toLocaleString(\"en-IN\");\r\n  $(\"statTeachers\").textContent = activeStaff.filter((staff) => lower(staff.role) === \"teacher\").length.toLocaleString(\"en-IN\");\r\n  $(\"statLibrarians\").textContent = activeStaff.filter((staff) => lower(staff.role) === \"librarian\").length.toLocaleString(\"en-IN\");\r\n  $(\"statAccountants\").textContent = activeStaff.filter((staff) => lower(staff.role) === \"accountant\").length.toLocaleString(\"en-IN\");\r\n}\r\n\r\nfunction matchesSearch(staff, search) {\n  if (!search) return true;\r\n  return [\r\n    staff.name,\r\n    staff.email,\r\n    staff.role,\r\n    staff.teacherId,\r\n    staff.staffId,\r\n      staff.employeeId,\r\n      staff.class,\r\n      staff.section,\r\n      staff.subject,\r\n      staff.designation,\r\n      staff.department\r\n  ].some((value) => lower(value).includes(search));\r\n}\n\nfunction resetStaffPage() {\n  staffPage = 1;\n}\n\nfunction renderStaff() {\n  $(\"staffList\").removeAttribute(\"aria-busy\");\n  setStats();\n  const search = lower($(\"staffSearch\").value);\n  const roleFilter = $(\"roleFilter\").value;\n  const statusFilter = $(\"statusFilter\").value;\n  const pageSize = Math.max(1, Number($(\"staffPageSize\")?.value || 10));\n  const rows = staffRecords\n    .filter((staff) => staffRoles.includes(lower(staff.role)))\r\n    .filter((staff) => roleFilter === \"all\" || lower(staff.role) === roleFilter)\r\n    .filter((staff) => statusFilter === \"all\" || (statusFilter === \"removed\" ? isRemoved(staff) : !isRemoved(staff)))\r\n    .filter((staff) => matchesSearch(staff, search))\r\n    .sort((a, b) => `${lower(a.role)}-${lower(a.name)}`.localeCompare(`${lower(b.role)}-${lower(b.name)}`));\r\n\n  if (!rows.length) {\n    $(\"staffList\").innerHTML = `<div class=\"empty\">No staff matched the current filters.</div>`;\n    $(\"staffPagination\").hidden = true;\n    return;\n  }\n\n  const totalPages = Math.max(1, Math.ceil(rows.length / pageSize));\n  staffPage = Math.min(Math.max(1, staffPage), totalPages);\n  const start = (staffPage - 1) * pageSize;\n  const visibleRows = rows.slice(start, start + pageSize);\n\n  $(\"staffList\").innerHTML = visibleRows.map((staff) => {\n    const role = lower(staff.role);\r\n    const removed = isRemoved(staff);\r\n    const meta = [\r\n      staff.email || \"No email\",\r\n      staffKey(staff) ? `ID: ${staffKey(staff)}` : \"\",\r\n      staff.class ? `Class ${staff.class}${staff.section ? \"-\" + staff.section : \"\"}` : \"\",\r\n      staff.subject ? `Subject: ${staff.subject}` : \"\",\r\n      lower(staff.role) === \"staff\" ? `Designation: ${staffDesignation(staff)}` : \"\",\r\n      staff.monthlySalary ? `Salary: Rs ${money(staff.monthlySalary).toLocaleString(\"en-IN\")}` : \"\"\r\n    ].filter(Boolean).join(\" | \");\r\n    return `\r\n      <article class=\"staff-row\">\r\n        <div class=\"identity\">\r\n          <div class=\"avatar\">${escapeHtml(initials(staff.name || staff.email, role[0] || \"S\"))}</div>\r\n          <div class=\"staff-main\">\r\n            <strong>${escapeHtml(staff.name || \"Unnamed Staff\")}</strong>\r\n            <small>${escapeHtml(meta)}</small>\r\n            <div class=\"chips\">\r\n              <span class=\"chip ${escapeHtml(role)}\">${escapeHtml(roleLabel(role))}</span>\r\n              ${removed ? `<span class=\"chip removed\">Removed</span>` : `<span class=\"chip\">Active</span>`}\r\n            </div>\r\n          </div>\r\n        </div>\r\n        <div class=\"row-actions\">\r\n          <button class=\"btn btn-light\" type=\"button\" onclick=\"window.location.href='#/teacher-profile.html?id=${escapeHtml(staff.uid)}'\"><i class=\"fas fa-id-card\"></i> View Profile</button>\r\n          <button class=\"btn btn-light\" type=\"button\" onclick=\"openEditStaff('${escapeHtml(staff.uid)}')\"><i class=\"fas fa-pen\"></i> Edit</button>\r\n          ${removed\r\n            ? `<button class=\"btn btn-success\" type=\"button\" onclick=\"setStaffRemoved('${escapeHtml(staff.uid)}', false)\"><i class=\"fas fa-user-check\"></i> Activate</button>`\r\n            : `<button class=\"btn btn-danger\" type=\"button\" onclick=\"setStaffRemoved('${escapeHtml(staff.uid)}', true)\"><i class=\"fas fa-user-slash\"></i> Remove</button>`}\r\n        </div>\r\n      </article>\r\n    `;\n  }).join(\"\");\n\n  $(\"staffPagination\").hidden = rows.length <= pageSize;\n  $(\"staffPaginationInfo\").textContent = `Showing ${start + 1}-${Math.min(start + pageSize, rows.length)} of ${rows.length} staff`;\n  $(\"staffPrevPage\").disabled = staffPage <= 1;\n  $(\"staffNextPage\").disabled = staffPage >= totalPages;\n}\n\r\nfunction renderSalaryStaffOptions() {\n  const activeStaff = staffRecords.filter((staff) => !isRemoved(staff));\r\n  $(\"salaryStaffSelect\").innerHTML = activeStaff.length\r\n    ? `<option value=\"\">Select staff</option>${activeStaff.map((staff) => `<option value=\"${escapeHtml(staff.uid)}\">${escapeHtml(staff.name || staff.email)} - ${escapeHtml(roleLabel(lower(staff.role)))}${staff.monthlySalary ? ` (Rs ${money(staff.monthlySalary).toLocaleString(\"en-IN\")})` : \"\"}</option>`).join(\"\")}`\r\n    : `<option value=\"\">No active staff found</option>`;\r\n}\n\nfunction salaryStatusClass(status, net, paid) {\n  const value = lower(status || salaryStatus(net, paid));\n  if (value.includes(\"paid\") && !value.includes(\"partial\")) return \"paid\";\n  if (value.includes(\"partial\")) return \"partial\";\n  return \"unpaid\";\n}\n\nfunction renderSalaryPlaceholder() {\n  $(\"activeSalaryHint\").className = \"salary-breakdown-card\";\n  $(\"activeSalaryHint\").innerHTML = `\n    <div class=\"salary-breakdown-head\">\n      <div>\n        <strong>Salary Breakdown</strong>\n        <span>Select a teacher or staff member to preview monthly salary details.</span>\n      </div>\n      <span class=\"salary-status-pill\">Ready</span>\n    </div>\n    <div class=\"salary-breakdown-grid\">\n      <div class=\"salary-breakdown-box base\"><span>Base Salary</span><strong>Rs 0</strong></div>\n      <div class=\"salary-breakdown-box\"><span>Net Salary</span><strong>Rs 0</strong></div>\n      <div class=\"salary-breakdown-box paid\"><span>Paid</span><strong>Rs 0</strong></div>\n      <div class=\"salary-breakdown-box due\"><span>Pending</span><strong>Rs 0</strong></div>\n    </div>\n    <div class=\"salary-breakdown-note\">Select a staff member to view salary, status, and payment history here.</div>\n  `;\n}\n\nfunction renderSalaryBreakdown(record = null, staff = null) {\n  const selectedStaff = staff || staffRecords.find((item) => item.uid === (record?.staffUid || record?.teacherUid || $(\"salaryStaffSelect\")?.value));\n  if (!record && !selectedStaff) {\n    renderSalaryPlaceholder();\n    return;\n  }\n  const base = money(record?.baseSalary ?? selectedStaff?.monthlySalary);\n  const net = money(record?.netSalary ?? base);\n  const paid = money(record?.paidAmount);\n  const due = money(record?.remainingAmount ?? Math.max(net - paid, 0));\n  const status = record?.status || salaryStatus(net, paid);\n  const staffName = record?.staffName || record?.teacherName || selectedStaff?.name || selectedStaff?.email || \"Selected Staff\";\n  const staffRole = record?.staffRole || selectedStaff?.role || \"staff\";\n  const staffId = record?.staffId || record?.teacherId || staffKey(selectedStaff) || \"-\";\n  const month = record?.monthLabel || monthLabel(record?.monthKey || $(\"salaryMonth\")?.value || currentMonth());\n  const session = record?.session || \"Current session\";\n  const payments = Array.isArray(record?.payments) ? record.payments.slice().reverse() : [];\n  $(\"activeSalaryHint\").className = \"salary-breakdown-card\";\n  $(\"activeSalaryHint\").innerHTML = `\n    <div class=\"salary-breakdown-head\">\n      <div>\n        <strong>${escapeHtml(staffName)}</strong>\n        <span>${escapeHtml(roleLabel(staffRole))} | ID: ${escapeHtml(staffId)} | ${escapeHtml(month)} | ${escapeHtml(session)}</span>\n      </div>\n      <span class=\"salary-status-pill ${salaryStatusClass(status, net, paid)}\">${escapeHtml(status)}</span>\n    </div>\n    <div class=\"salary-breakdown-grid\">\n      <div class=\"salary-breakdown-box base\"><span>Base Salary</span><strong>${moneyLabel(base)}</strong></div>\n      <div class=\"salary-breakdown-box\"><span>Net Salary</span><strong>${moneyLabel(net)}</strong></div>\n      <div class=\"salary-breakdown-box paid\"><span>Paid</span><strong>${moneyLabel(paid)}</strong></div>\n      <div class=\"salary-breakdown-box due\"><span>Pending</span><strong>${moneyLabel(due)}</strong></div>\n    </div>\n    <div class=\"salary-payment-history\">\n      <h4>Payment History</h4>\n      ${payments.length ? payments.map((payment) => `\n        <div class=\"salary-payment-item\">\n          <div><strong>${moneyLabel(payment.amount)}</strong><small>${escapeHtml(payment.note || payment.paymentMode || \"Salary payment\")}</small></div>\n          <span>${escapeHtml(payment.paymentDate ? new Date(`${payment.paymentDate}T00:00:00`).toLocaleDateString(\"en-IN\") : \"Date not set\")}</span>\n        </div>\n      `).join(\"\") : `<div class=\"salary-breakdown-note\">No payment history has been recorded for this salary yet.</div>`}\n    </div>\n    ${record ? \"\" : `<div class=\"salary-breakdown-note\">After the salary record is generated, paid and pending amounts will update here.</div>`}\n  `;\n}\n\nfunction renderSalaryRecords() {\n  $(\"salaryRecordsList\").removeAttribute(\"aria-busy\");\n  if ($(\"salaryRecordsList\").hidden || $(\"salaryRecordsList\").style.display === \"none\") return;\n  if (!salaryRecords.length) {\n    $(\"salaryRecordsList\").innerHTML = `<div class=\"empty\">No staff salary records yet.</div>`;\r\n    return;\r\n  }\r\n  $(\"salaryRecordsList\").innerHTML = salaryRecords\n    .slice()\n    .sort((a, b) => `${b.monthKey || \"\"}-${lower(b.staffName || b.teacherName)}`.localeCompare(`${a.monthKey || \"\"}-${lower(a.staffName || a.teacherName)}`))\n    .map((record) => {\r\n      const paid = money(record.paidAmount);\r\n      const net = money(record.netSalary);\r\n      const due = money(record.remainingAmount);\r\n      return `\r\n        <article class=\"salary-row\">\r\n          <div>\r\n            <strong>${escapeHtml(record.staffName || record.teacherName || \"Staff\")} - ${escapeHtml(record.monthLabel || monthLabel(record.monthKey))}</strong>\r\n            <small class=\"muted\">${escapeHtml(roleLabel(record.staffRole || record.role))} | Net Rs ${net.toLocaleString(\"en-IN\")} | Paid Rs ${paid.toLocaleString(\"en-IN\")} | Due Rs ${due.toLocaleString(\"en-IN\")} | ${escapeHtml(record.status || \"Unpaid\")}</small>\r\n          </div>\r\n          <button class=\"btn btn-light\" type=\"button\" onclick=\"selectSalaryRecord('${escapeHtml(record.id)}')\"><i class=\"fas fa-arrow-pointer\"></i> Select</button>\r\n        </article>\r\n      `;\r\n    }).join(\"\");\r\n}\r\n\r\nasync function loadSalaryRecords() {\n  if (!adminUID) return;\n  showSalaryLoader();\n  try {\n    const [teacherSnapshot, staffSnapshot] = await Promise.all([\n      getDocs(collection(db, \"schools\", adminUID, \"teacher_salary_records\")).catch(() => ({ docs: [] })),\n      getDocs(collection(db, \"schools\", adminUID, \"staff_salary_records\")).catch(() => ({ docs: [] }))\n    ]);\n    const recordsById = new Map();\n    teacherSnapshot.docs.forEach((item) => {\n      const data = item.data();\n      recordsById.set(`teacher:${item.id}`, {\n        id: item.id,\n        ...data,\n        staffUid: data.staffUid || data.teacherUid || \"\",\n        staffId: data.staffId || data.teacherId || \"\",\n        staffName: data.staffName || data.teacherName || \"Teacher\",\n        staffEmail: data.staffEmail || data.teacherEmail || \"\",\n        staffRole: \"teacher\",\n        sourceType: \"teacher_salary\",\n        salaryCollection: \"teacher_salary_records\"\n      });\n    });\n    staffSnapshot.docs.forEach((item) => {\n      const data = item.data();\n      const role = lower(data.staffRole || data.role);\n      const key = role === \"teacher\" ? `teacher:${item.id}` : `staff:${item.id}`;\n      if (recordsById.has(key)) return;\n      recordsById.set(key, {\n        id: item.id,\n        ...data,\n        staffRole: role || \"staff\",\n        sourceType: role === \"teacher\" ? \"teacher_salary\" : \"staff_salary\",\n        salaryCollection: role === \"teacher\" ? \"teacher_salary_records\" : \"staff_salary_records\"\n      });\n    });\n    salaryRecords = Array.from(recordsById.values());\n    renderSalaryRecords();\n    if ($(\"salaryStaffSelect\")?.value) previewSelectedStaffSalary();\n  } catch (error) {\n    console.warn(\"Unable to load staff salary records\", error);\n    $(\"salaryRecordsList\").removeAttribute(\"aria-busy\");\n    $(\"salaryRecordsList\").innerHTML = `<div class=\"empty\">Unable to load staff salary records.</div>`;\n  }\n}\n\r\nfunction setActiveSalaryRecord(record) {\n  activeSalaryRecord = record || null;\n  activeSalaryRecordId = record?.id || \"\";\n  $(\"recordSalaryBtn\").disabled = !record;\n  renderSalaryBreakdown(record);\n  $(\"paymentAmount\").value = record && record.remainingAmount > 0 ? record.remainingAmount : \"\";\n}\n\nfunction previewSelectedStaffSalary() {\n  const staff = staffRecords.find((item) => item.uid === $(\"salaryStaffSelect\").value);\n  const monthKey = $(\"salaryMonth\").value || currentMonth();\n  const existing = salaryRecords.find((record) => {\n    const uid = record.staffUid || record.teacherUid;\n    return uid === staff?.uid && (!record.monthKey || record.monthKey === monthKey);\n  });\n  if (existing) {\n    setActiveSalaryRecord(existing);\n    return;\n  }\n  activeSalaryRecord = null;\n  activeSalaryRecordId = \"\";\n  $(\"recordSalaryBtn\").disabled = true;\n  renderSalaryBreakdown(null, staff || null);\n}\n\r\nasync function ensureStaffSalaryRecord() {\n  const button = $(\"generateSalaryBtn\");\n  const staffUid = $(\"salaryStaffSelect\").value;\n  const monthKey = $(\"salaryMonth\").value;\n  const staff = staffRecords.find((item) => item.uid === staffUid);\n  if (!staff) return alert(\"Select staff first.\");\n  if (!monthKey) return alert(\"Select salary month first.\");\n  const role = lower(staff.role);\n  const salaryCollection = salaryCollectionForRole(role);\n  const baseSalary = money(staff.monthlySalary);\n  if (baseSalary <= 0 && !confirm(\"Monthly salary is 0. Generate salary record anyway?\")) return null;\n  setStaffBusy(button, true, `<i class=\"fas fa-spinner fa-spin\"></i> Generating...`);\n  $(\"activeSalaryHint\").innerHTML = `<div class=\"staff-inline-loader\"><i class=\"fas fa-spinner fa-spin\"></i> Preparing salary record...</div>`;\n  try {\n    const recordId = `${staffUid}_${monthKey}`;\n    const recordRef = doc(db, \"schools\", adminUID, salaryCollection, recordId);\n    const existingSnap = await getDoc(recordRef);\n    const existing = existingSnap.exists() ? existingSnap.data() : {};\n    let salarySessionId = existing.sessionId || \"\";\n    let salarySessionLabel = existing.session || \"\";\n    if (!salarySessionId) {\n      try {\n        let viewSessionId = \"\";\n        try { viewSessionId = localStorage.getItem(\"schoolix.viewSessionId\") || \"\"; } catch (_) {}\n        const activeSnap = await getDoc(doc(db, \"schools\", adminUID, \"settings\", \"activeSession\"));\n        salarySessionId = viewSessionId || (activeSnap.exists() ? activeSnap.data().sessionId || \"\" : \"\");\n        if (salarySessionId) {\n          const sessionSnap = await getDoc(doc(db, \"schools\", adminUID, \"sessions\", salarySessionId));\n          if (sessionSnap.exists()) {\n            const sessionData = sessionSnap.data();\n            salarySessionLabel = sessionData.session || sessionData.name || salarySessionId;\n          }\n        }\n      } catch (error) {\n        console.warn(\"Unable to attach session to salary record\", error);\n      }\n    }\n    const payments = Array.isArray(existing.payments) ? existing.payments : [];\n    const paidAmount = money(payments.reduce((sum, payment) => sum + Number(payment.amount || 0), 0));\n    const netSalary = money(existing.netSalary ?? baseSalary);\n    const remainingAmount = money(Math.max(netSalary - paidAmount, 0));\n    const payload = {\n      staffUid,\n      staffId: staffKey(staff),\n      staffName: staff.name || staff.email || \"Staff\",\n      staffEmail: staff.email || \"\",\n      staffRole: role,\n      designation: staffDesignation(staff),\n      department: staff.department || \"\",\n      monthKey,\n      monthLabel: monthLabel(monthKey),\n      sessionId: salarySessionId,\n      session: salarySessionLabel,\n      baseSalary,\n      netSalary,\n      paidAmount,\n      remainingAmount,\n      status: salaryStatus(netSalary, paidAmount),\n      payments,\n      sourceType: role === \"teacher\" ? \"teacher_salary\" : \"staff_salary\",\n      updatedAt: serverTimestamp(),\n      updatedBy: auth.currentUser?.email || \"admin\"\n    };\n    if (role === \"teacher\") {\n      payload.teacherUid = staffUid;\n      payload.teacherId = staff.teacherId || staffKey(staff);\n      payload.teacherName = staff.name || staff.email || \"Teacher\";\n      payload.teacherEmail = staff.email || \"\";\n    }\n    if (!existingSnap.exists()) payload.generatedAt = serverTimestamp();\n    await setDoc(recordRef, payload, { merge: true });\n    const record = { id: recordId, ...payload, salaryCollection };\n    activeSalaryRecordId = recordId;\n    activeSalaryRecord = record;\n    await loadSalaryRecords();\n    setActiveSalaryRecord(salaryRecords.find((item) => item.id === recordId) || record);\n    return activeSalaryRecord;\n  } finally {\n    setStaffBusy(button, false);\n  }\n}\n\r\nasync function recordStaffSalaryPayment(event) {\n  event.preventDefault();\n  const button = $(\"recordSalaryBtn\");\n  if (!activeSalaryRecordId || !activeSalaryRecord) return alert(\"Generate or select salary record first.\");\n  const amount = money($(\"paymentAmount\").value);\n  if (amount <= 0 || !$(\"paymentDate\").value) return alert(\"Enter payment amount and payment date.\");\n  setStaffBusy(button, true, `<i class=\"fas fa-spinner fa-spin\"></i> Recording...`);\n  try {\n    const salaryCollection = salaryCollectionForRecord(activeSalaryRecord);\n    const recordRef = doc(db, \"schools\", adminUID, salaryCollection, activeSalaryRecordId);\n    const snap = await getDoc(recordRef);\n    if (!snap.exists()) return alert(\"Salary record no longer exists.\");\n    const record = {\n      id: snap.id,\n      ...snap.data(),\n      sourceType: salaryCollection === \"teacher_salary_records\" ? \"teacher_salary\" : \"staff_salary\",\n      salaryCollection\n    };\n    const payments = Array.isArray(record.payments) ? [...record.payments] : [];\n    const payment = {\n      amount,\n      paymentDate: $(\"paymentDate\").value,\n      paymentMode: $(\"paymentMode\").value,\n      note: clean($(\"paymentNote\").value),\n      recordedBy: auth.currentUser?.email || \"admin\",\n      recordedAt: new Date().toISOString(),\n      ledgerTransactionId: newLedgerTransactionId(\"SAL\")\n    };\n    payments.push(payment);\n    const paidAmount = money(payments.reduce((sum, item) => sum + Number(item.amount || 0), 0));\n    const remainingAmount = money(Math.max(Number(record.netSalary || 0) - paidAmount, 0));\n    await setDoc(recordRef, {\n      payments,\n      paidAmount,\n      remainingAmount,\n      status: salaryStatus(Number(record.netSalary || 0), paidAmount),\n      updatedAt: serverTimestamp(),\n      updatedBy: auth.currentUser?.email || \"admin\"\n    }, { merge: true });\n    await syncStaffSalaryDebit({\n      db,\n      schoolId: adminUID,\n      actor: { uid: auth.currentUser.uid, email: auth.currentUser.email, role: \"admin\" },\n      recordId: activeSalaryRecordId,\n      record,\n      payment,\n      paymentIndex: payments.length - 1\n    });\n    $(\"paymentAmount\").value = \"\";\n    $(\"paymentNote\").value = \"\";\n    await loadSalaryRecords();\n    setActiveSalaryRecord(salaryRecords.find((item) => item.id === activeSalaryRecordId) || null);\n    alert(\"Salary payment recorded and debited in School Accounts.\");\n  } finally {\n    setStaffBusy(button, false);\n  }\n}\n\r\nasync function loadStaff() {\n  if (!adminUID) return;\n  showStaffListLoader();\n  showSalaryLoader(\"Waiting for staff records...\");\n  $(\"salaryStaffSelect\").innerHTML = `<option value=\"\">Loading staff...</option>`;\n  try {\n    const [adminSnap, schoolSnap] = await Promise.all([\r\n      getDocs(query(collection(db, \"users\"), where(\"adminId\", \"==\", adminUID))),\r\n      getDocs(query(collection(db, \"users\"), where(\"schoolId\", \"==\", adminUID)))\r\n    ]);\r\n    const seen = new Set();\r\n    staffRecords = [];\r\n    [...adminSnap.docs, ...schoolSnap.docs].forEach((docSnap) => {\r\n      if (seen.has(docSnap.id)) return;\r\n      seen.add(docSnap.id);\r\n      const data = docSnap.data();\r\n      if (!staffRoles.includes(lower(data.role))) return;\r\n      staffRecords.push({ uid: docSnap.id, ...data });\r\n    });\r\n    renderSalaryStaffOptions();\r\n    renderStaff();\r\n    await loadSalaryRecords();\r\n  } catch (error) {\n    console.error(\"Staff load failed:\", error);\n    $(\"staffList\").removeAttribute(\"aria-busy\");\n    $(\"salaryRecordsList\").removeAttribute(\"aria-busy\");\n    $(\"staffList\").innerHTML = `<div class=\"empty\">Unable to load staff: ${escapeHtml(error.message)}</div>`;\n    $(\"salaryStaffSelect\").innerHTML = `<option value=\"\">Unable to load staff</option>`;\n  }\n}\n\r\nasync function createStaff(event) {\r\n  event.preventDefault();\r\n  const role = $(\"staffRole\").value;\r\n  const name = clean($(\"staffName\").value);\r\n  const email = lower($(\"staffEmail\").value);\r\n  const password = $(\"staffPassword\").value;\r\n  const needsLogin = role !== \"staff\";\r\n  const button = $(\"createStaffBtn\");\r\n  const original = button.innerHTML;\r\n  if (!role || !name) {\r\n    alert(\"Please fill role and name.\");\r\n    return;\r\n  }\r\n  if (needsLogin && (!email || password.length < 6)) {\r\n    alert(\"Please fill email and minimum 6 character password for portal login.\");\r\n    return;\r\n  }\r\n  if (role === \"teacher\" && (!clean($(\"teacherClass\").value) || !clean($(\"teacherSection\").value))) {\r\n    alert(\"Please enter class and section for teacher accounts.\");\r\n    return;\r\n  }\r\n  if (role === \"staff\" && !clean($(\"staffDesignation\").value)) {\r\n    alert(\"Please tell who this Other Staff is, for example Receptionist, Guard, Driver, Clerk.\");\r\n    return;\r\n  }\r\n\r\n  try {\r\n    button.disabled = true;\r\n    button.innerHTML = `<i class=\"fas fa-spinner fa-spin\"></i> Creating...`;\r\n    const userRef = needsLogin ? null : doc(collection(db, \"users\"));\r\n    const userCred = needsLogin ? await createUserWithEmailAndPassword(staffCreatorAuth, email, password) : null;\r\n    const uid = needsLogin ? userCred.user.uid : userRef.id;\r\n    const generatedId = await generateStaffId(role);\r\n    const base = {\r\n      name,\r\n      email,\r\n      role,\r\n      adminId: adminUID,\r\n      schoolId: adminUID,\r\n      loginEnabled: needsLogin,\r\n      portalAccess: needsLogin,\r\n      staffLocalOnly: !needsLogin,\r\n      active: true,\r\n      panelStatus: \"active\",\r\n      createdAt: serverTimestamp(),\r\n      updatedAt: serverTimestamp()\r\n    };\r\n    const roleFields = role === \"teacher\"\r\n      ? {\r\n          teacherId: generatedId,\r\n          class: clean($(\"teacherClass\").value),\r\n          section: clean($(\"teacherSection\").value),\r\n          subject: clean($(\"teacherSubject\").value),\r\n          monthlySalary: money($(\"staffSalary\").value)\r\n        }\r\n      : {\r\n          staffId: generatedId,\r\n          designation: role === \"staff\" ? clean($(\"staffDesignation\").value) : roleLabel(role),\r\n          department: clean($(\"staffDepartment\").value),\r\n          monthlySalary: money($(\"staffSalary\").value)\r\n        };\r\n\r\n    await setDoc(needsLogin ? doc(db, \"users\", uid) : userRef, { ...base, ...roleFields });\r\n    if (role === \"teacher\") {\r\n      await setDoc(doc(db, \"schools\", adminUID, \"teacher_salaries\", uid), {\r\n        teacherUid: uid,\r\n        teacherId: generatedId,\r\n        teacherName: name,\r\n        teacherEmail: email,\r\n        monthlySalary: money($(\"staffSalary\").value),\r\n        adminId: adminUID,\r\n        schoolId: adminUID,\r\n        createdAt: serverTimestamp(),\r\n        updatedAt: serverTimestamp()\r\n      }, { merge: true });\r\n    }\r\n    $(\"staffForm\").reset();\n    $(\"staffRole\").value = \"teacher\";\r\n    toggleTeacherFields();\r\n    alert(needsLogin ? `${roleLabel(role)} account created successfully.` : `${roleLabel(role)} details saved without login access.`);\r\n    await loadStaff();\r\n  } catch (error) {\r\n    alert(error.message || \"Unable to create staff account.\");\r\n  } finally {\r\n    button.disabled = false;\r\n    button.innerHTML = original;\r\n  }\r\n}\r\n\r\nfunction toggleTeacherFields() {\r\n  const role = $(\"staffRole\").value;\r\n  const isOtherStaff = role === \"staff\";\r\n  $(\"teacherFields\").classList.toggle(\"show\", role === \"teacher\");\r\n  $(\"otherFields\").classList.toggle(\"show\", isOtherStaff);\r\n  $(\"staffEmailField\").classList.toggle(\"is-hidden\", isOtherStaff);\r\n  $(\"staffPasswordField\").classList.toggle(\"is-hidden\", isOtherStaff);\r\n  $(\"staffEmail\").required = !isOtherStaff;\r\n  $(\"staffPassword\").required = !isOtherStaff;\r\n  $(\"staffDesignation\").required = isOtherStaff;\r\n  if (isOtherStaff) {\r\n    $(\"staffEmail\").value = \"\";\r\n    $(\"staffPassword\").value = \"\";\r\n    $(\"createStaffBtn\").innerHTML = `<i class=\"fas fa-user-plus\"></i> Save Staff Details`;\r\n  } else {\r\n    $(\"createStaffBtn\").innerHTML = `<i class=\"fas fa-user-plus\"></i> Create Staff Account`;\r\n  }\r\n}\r\n\r\nfunction openEditStaff(uid) {\r\n  const staff = staffRecords.find((item) => item.uid === uid);\r\n  if (!staff) return alert(\"Staff record not found.\");\r\n  $(\"editUid\").value = uid;\r\n  $(\"editName\").value = staff.name || \"\";\r\n  $(\"editEmail\").value = staff.email || \"\";\r\n  $(\"editRole\").value = lower(staff.role) || \"staff\";\r\n  $(\"editStaffId\").value = staffKey(staff);\r\n  $(\"editClass\").value = staff.class || \"\";\r\n  $(\"editSection\").value = staff.section || \"\";\r\n  $(\"editSubject\").value = staff.subject || \"\";\r\n  $(\"editSalary\").value = staff.monthlySalary || \"\";\r\n  $(\"editDesignation\").value = staff.designation || \"\";\r\n  $(\"editDepartment\").value = staff.department || \"\";\r\n  $(\"editDialog\").classList.add(\"show\");\r\n  $(\"editDialog\").setAttribute(\"aria-hidden\", \"false\");\r\n}\r\n\r\nfunction closeEditDialog() {\r\n  $(\"editDialog\").classList.remove(\"show\");\r\n  $(\"editDialog\").setAttribute(\"aria-hidden\", \"true\");\r\n}\r\n\r\nasync function saveStaff(event) {\n  event.preventDefault();\n  const button = event.submitter || $(\"editForm\").querySelector('button[type=\"submit\"]');\n  const uid = $(\"editUid\").value;\n  const role = $(\"editRole\").value;\r\n  const staffId = clean($(\"editStaffId\").value);\r\n  if (!uid) return;\r\n  const payload = {\r\n    name: clean($(\"editName\").value),\r\n    email: lower($(\"editEmail\").value),\r\n    role,\r\n    class: clean($(\"editClass\").value),\r\n    section: clean($(\"editSection\").value),\r\n    subject: clean($(\"editSubject\").value),\r\n    designation: clean($(\"editDesignation\").value),\r\n    department: clean($(\"editDepartment\").value),\r\n    monthlySalary: money($(\"editSalary\").value),\r\n    updatedAt: serverTimestamp()\r\n  };\r\n  if (role === \"teacher\") payload.teacherId = staffId;\n  else payload.staffId = staffId;\n  setStaffBusy(button, true, `<i class=\"fas fa-spinner fa-spin\"></i> Saving...`);\n  try {\n    await setDoc(doc(db, \"users\", uid), payload, { merge: true });\n    if (role === \"teacher\") {\n      await setDoc(doc(db, \"schools\", adminUID, \"teacher_salaries\", uid), {\n        teacherUid: uid,\n        teacherId: staffId,\n        teacherName: payload.name,\n        teacherEmail: payload.email,\n        monthlySalary: payload.monthlySalary,\n        adminId: adminUID,\n        schoolId: adminUID,\n        updatedAt: serverTimestamp()\n      }, { merge: true });\n    }\n    closeEditDialog();\n    await loadStaff();\n    alert(\"Staff details updated.\");\n  } finally {\n    setStaffBusy(button, false);\n  }\n}\n\r\nfunction selectSalaryRecord(recordId) {\n  const record = salaryRecords.find((item) => item.id === recordId);\n  if (!record) return alert(\"Salary record not found.\");\n  $(\"salaryStaffSelect\").value = record.staffUid || record.teacherUid || \"\";\n  $(\"salaryMonth\").value = record.monthKey || currentMonth();\n  setActiveSalaryRecord(record);\n}\n\r\nasync function setStaffRemoved(uid, removed) {\n  const staff = staffRecords.find((item) => item.uid === uid);\n  if (!staff) return alert(\"Staff record not found.\");\n  const action = removed ? \"remove from active staff\" : \"activate\";\n  if (!confirm(`${action.charAt(0).toUpperCase() + action.slice(1)} ${staff.name || staff.email}?`)) return;\n  const button = document.activeElement?.tagName === \"BUTTON\" ? document.activeElement : null;\n  setStaffBusy(button, true, `<i class=\"fas fa-spinner fa-spin\"></i> ${removed ? \"Removing...\" : \"Activating...\"}`);\n  try {\n    await setDoc(doc(db, \"users\", uid), {\n      active: !removed,\n      removedFromPanel: removed,\n      panelStatus: removed ? \"removed\" : \"active\",\n      removedAt: removed ? serverTimestamp() : null,\n      removedBy: removed ? (auth.currentUser?.email || \"admin\") : \"\",\n      updatedAt: serverTimestamp()\n    }, { merge: true });\n    if (lower(staff.role) === \"teacher\") {\n      await setDoc(doc(db, \"schools\", adminUID, \"teacher_salaries\", uid), {\n        removedFromPanel: removed,\n        panelStatus: removed ? \"removed\" : \"active\",\n        updatedAt: serverTimestamp()\n      }, { merge: true });\n    }\n    await loadStaff();\n  } finally {\n    setStaffBusy(button, false);\n  }\n}\n\r\nonAuthStateChanged(auth, async (user) => {\n  showStaffListLoader(\"Checking admin access...\");\n  showSalaryLoader(\"Preparing salary desk...\");\n  if (!user) {\n    window.location.href = \"#/index.html\";\n    return;\n  }\n  try {\n    const userDoc = await getDoc(doc(db, \"users\", user.uid));\n    const role = lower(userDoc.exists() ? userDoc.data().role : \"\");\n    if (!userDoc.exists() || role !== \"admin\") {\n      alert(\"Access denied. Only admin can manage staff.\");\n      window.location.href = \"#/index.html\";\n      return;\n    }\n    adminUID = user.uid;\n    await loadStaff();\n  } catch (error) {\n    console.error(\"Staff management auth failed:\", error);\n    $(\"staffList\").removeAttribute(\"aria-busy\");\n    $(\"salaryRecordsList\").removeAttribute(\"aria-busy\");\n    $(\"staffList\").innerHTML = `<div class=\"empty\">Unable to open staff management.</div>`;\n    $(\"salaryRecordsList\").innerHTML = `<div class=\"empty\">Salary desk unavailable.</div>`;\n  }\n});\n\r\n$(\"staffForm\").addEventListener(\"submit\", createStaff);\r\n$(\"staffRole\").addEventListener(\"change\", toggleTeacherFields);\r\n$(\"staffSearch\").addEventListener(\"input\", () => { resetStaffPage(); renderStaff(); });\n$(\"roleFilter\").addEventListener(\"change\", () => { resetStaffPage(); renderStaff(); });\n$(\"statusFilter\").addEventListener(\"change\", () => { resetStaffPage(); renderStaff(); });\n$(\"staffPageSize\").addEventListener(\"change\", () => { resetStaffPage(); renderStaff(); });\n$(\"staffPrevPage\").addEventListener(\"click\", () => { staffPage = Math.max(1, staffPage - 1); renderStaff(); });\n$(\"staffNextPage\").addEventListener(\"click\", () => { staffPage += 1; renderStaff(); });\n$(\"salaryStaffSelect\").addEventListener(\"change\", previewSelectedStaffSalary);\n$(\"salaryMonth\").addEventListener(\"change\", previewSelectedStaffSalary);\n$(\"editForm\").addEventListener(\"submit\", saveStaff);\n$(\"generateSalaryBtn\").addEventListener(\"click\", () => ensureStaffSalaryRecord().catch((error) => alert(error.message || \"Unable to generate salary record.\")));\r\n$(\"salaryForm\").addEventListener(\"submit\", (event) => recordStaffSalaryPayment(event).catch((error) => alert(error.message || \"Unable to record salary payment.\")));\r\n$(\"closeEditBtn\").addEventListener(\"click\", closeEditDialog);\r\n$(\"cancelEditBtn\").addEventListener(\"click\", closeEditDialog);\r\n$(\"editDialog\").addEventListener(\"click\", (event) => {\r\n  if (event.target === $(\"editDialog\")) closeEditDialog();\r\n});\r\nwindow.openEditStaff = openEditStaff;\r\nwindow.setStaffRemoved = setStaffRemoved;\r\nwindow.selectSalaryRecord = selectSalaryRecord;\r\n$(\"salaryMonth\").value = currentMonth();\n$(\"paymentDate\").value = todayISO();\ntoggleTeacherFields();\nrenderSalaryPlaceholder();\nshowStaffListLoader(\"Loading staff management...\");\nshowSalaryLoader(\"Loading salary desk...\");\n"},{"attributes":{"type":"module","src":"access-control.js?v=accountant-guard-20260806-3"},"text":""},{"attributes":{"src":"schoolix-polish.js"},"text":""},{"attributes":{"src":"admin-shell.js?v=staff-loaders-20260806"},"text":""}]};
